const OBJ = {"domains":[{"id":1,"name":"General Security Concepts","weight":12},{"id":2,"name":"Threats, Vulnerabilities, and Mitigations","weight":22},{"id":3,"name":"Security Architecture","weight":18},{"id":4,"name":"Security Operations","weight":28},{"id":5,"name":"Security Program Management and Oversight","weight":20}],"objectives":{"1.1":"Compare and contrast various types of security controls","1.2":"Summarize fundamental security concepts","1.3":"Explain the importance of change management processes","1.4":"Explain the importance of using appropriate cryptographic solutions","2.1":"Compare and contrast common threat actors and motivations","2.2":"Explain common threat vectors and attack surfaces","2.3":"Explain various types of vulnerabilities","2.4":"Given a scenario, analyze indicators of malicious activity","2.5":"Explain the purpose of mitigation techniques used to secure the enterprise","3.1":"Compare and contrast security implications of different architecture models","3.2":"Given a scenario, apply security principles to secure enterprise infrastructure","3.3":"Compare and contrast concepts and strategies to protect data","3.4":"Explain the importance of resilience and recovery in security architecture","4.1":"Given a scenario, apply common security techniques to computing resources","4.2":"Explain the security implications of proper hardware, software, and data asset management","4.3":"Explain various activities associated with vulnerability management","4.4":"Explain security alerting and monitoring concepts and tools","4.5":"Given a scenario, modify enterprise capabilities to enhance security","4.6":"Given a scenario, implement and maintain identity and access management","4.7":"Explain the importance of automation and orchestration related to secure operations","4.8":"Explain appropriate incident response activities","4.9":"Given a scenario, use data sources to support an investigation","5.1":"Summarize elements of effective security governance","5.2":"Explain elements of the risk management process","5.3":"Explain the processes associated with third-party risk assessment and management","5.4":"Summarize elements of effective security compliance","5.5":"Explain types and purposes of audits and assessments","5.6":"Given a scenario, implement security awareness practices"},"sections":{"Fundamentals of Security":["1.1","1.2"],"Threat Actors":["2.1","1.2","2.2"],"Physical Security":["1.2","2.4"],"Social Engineering":["2.2","5.6"],"Malware":["2.4"],"Data Protection":["3.3","1.4","4.2","4.4","5.1"],"Cryptographic Solutions":["1.4","2.3","2.4"],"Risk Management":["5.2"],"Third-party Vendor Risks":["5.3","2.2","2.3"],"Governance and Compliance":["5.1","5.4"],"Asset and Change Management":["1.3","4.2","4.1"],"Audits and Assessments":["5.5"],"Cyber Resilience and Redundancy":["3.4"],"Security Architecture":["3.1","4.1"],"Security Infrastructure":["3.2","4.5"],"Identity and Access Management (IAM) Solutions":["4.6","2.4"],"Vulnerabilities and Attacks":["2.3","2.2","2.4","2.5","4.1"],"Malicious Activity":["2.4"],"Hardening":["2.5","4.1","4.5"],"Security Techniques":["4.1","4.5"],"Vulnerability Management":["4.3"],"Alerting and Monitoring":["4.4"],"Incident Response":["4.8"],"Investigating an Incident":["4.9"],"Automation and Orchestration":["4.7"],"Security Awareness":["5.6"]}};
const SCEN = [{"id":"S001","o":"1.1","d":1,"q":"After a series of after-hours thefts, a company installs bright lighting and posts signs stating that the premises are under 24/7 video surveillance. The cameras are not yet connected to a recorder. Which control type do the signs and lighting PRIMARILY represent?","a":["Compensating","Detective","Corrective","Deterrent"],"c":3,"e":"Deterrent controls discourage an attacker from attempting an action, which is exactly what visible lighting and warning signs do even when the cameras are not recording. Detective controls identify an event that has occurred or is occurring; unconnected cameras detect nothing. Corrective controls restore systems or limit damage after an incident. Compensating controls are alternative measures used when a primary control cannot be implemented."},{"id":"S002","o":"1.1","d":1,"q":"A legacy manufacturing controller cannot be patched because the vendor no longer supports it. The security team places the controller on an isolated VLAN with strict ACLs and enhanced monitoring. Which type of control has the team implemented?","a":["Corrective","Compensating","Deterrent","Directive"],"c":1,"e":"A compensating control is an alternative safeguard used when the preferred control, in this case patching, cannot be applied. Isolation and monitoring reduce the risk to an acceptable level instead. Directive controls instruct people what to do, such as policies. Corrective controls act after an incident to restore systems, while these measures are put in place in advance. Deterrent controls discourage attempts rather than reduce exposure."},{"id":"S003","o":"1.1","d":1,"q":"A security manager publishes an acceptable use policy that states employees must lock their workstations when leaving their desks. Which control category and type BEST describe this policy?","a":["Technical, preventive","Managerial, directive","Physical, deterrent","Operational, detective"],"c":1,"e":"A written policy issued by management is a managerial control, and because it tells people what behavior is expected, its type is directive. A technical preventive control would be an automatic screen lock enforced by Group Policy. Operational detective controls are carried out by people to identify events, such as log reviews. Physical deterrent controls are tangible measures such as fences or signage."},{"id":"S004","o":"1.1","d":1,"q":"An organization restores a compromised web server from a known good backup and then reapplies its security baseline. Which control type does this action represent?","a":["Directive","Corrective","Preventive","Detective"],"c":1,"e":"Corrective controls act after an incident to fix the problem and return systems to a secure state, which is what restoring from backup and reapplying the baseline achieves. Preventive controls stop an incident before it happens. Detective controls identify that an incident has occurred. Directive controls guide behavior through instructions or policy."},{"id":"S005","o":"1.1","d":1,"q":"Security guards at a data center walk the perimeter every hour and record anything unusual in a logbook. Which control category do these patrols BEST fit?","a":["Managerial","Compensating","Operational","Technical"],"c":2,"e":"Operational controls are procedures carried out by people as part of day-to-day activity, such as guard patrols and log keeping. Managerial controls are oversight and planning measures like risk assessments and policies. Technical controls are implemented by systems, such as firewalls. Compensating is a control type that substitutes for an unavailable primary control, not a category describing who performs it."},{"id":"S006","o":"1.1","d":1,"q":"An intrusion detection system generates an alert when it observes a port scan against the DMZ but does not block the traffic. Which control type is the IDS performing?","a":["Corrective","Detective","Preventive","Deterrent"],"c":1,"e":"An IDS identifies and reports suspicious activity, which is the defining function of a detective control. It would be preventive only if it blocked the traffic, as an IPS does. Corrective controls remediate after an event. Deterrent controls discourage attackers from trying, and an invisible IDS does not influence attacker behavior."},{"id":"S007","o":"1.1","d":1,"q":"A company requires two employees to be present whenever the vault containing backup tapes is opened, and both must sign an access register. What is the PRIMARY purpose of requiring two people?","a":["Prevent a single person from misusing access","Detect environmental hazards in the vault","Satisfy encryption requirements for tapes","Speed up recovery during an outage"],"c":0,"e":"Two-person control is a preventive measure that ensures no single individual can access or tamper with sensitive assets alone, reducing insider risk. It has nothing to do with environmental hazards, which are handled by sensors. It typically slows access rather than speeding recovery. Encryption of tapes is a separate technical control unrelated to how many people open the vault."},{"id":"S008","o":"1.1","d":1,"q":"Which of the following is an example of a technical preventive control?","a":["A security awareness poster about tailgating","A fire extinguisher in the server room","A quarterly review of firewall logs","A firewall rule that blocks inbound SMB from the internet"],"c":3,"e":"A firewall rule is enforced by technology and stops traffic before harm occurs, making it technical and preventive. A poster is a managerial or operational directive and deterrent measure. A log review is an operational detective activity. A fire extinguisher is a physical corrective control used after a fire starts."},{"id":"S009","o":"1.2","d":1,"q":"A sales manager digitally signs a contract proposal before emailing it to a client. Later, the manager claims they never sent the proposal. Which security concept allows the company to disprove this claim?","a":["Authorization","Non-repudiation","Availability","Confidentiality"],"c":1,"e":"Non-repudiation provides proof of origin so the sender cannot credibly deny sending a message; a digital signature created with the manager's private key provides this proof. Confidentiality keeps content secret from unauthorized parties. Availability ensures systems are accessible when needed. Authorization determines what an authenticated user is allowed to do."},{"id":"S010","o":"1.2","d":1,"q":"A company adopts a model in which every access request is evaluated based on user identity, device posture, and context, regardless of whether the request originates inside the corporate network. Which component makes the decision to grant or deny each request?","a":["Policy enforcement point","Implicit trust zone","Subject","Policy engine"],"c":3,"e":"In a zero trust architecture, the policy engine evaluates the request against policy and decides whether to allow it. The policy enforcement point is where that decision is applied, opening or closing the connection, but it does not make the decision. An implicit trust zone is the area after the enforcement point where traffic is trusted. The subject is the user or system making the request."},{"id":"S011","o":"1.2","d":1,"q":"An administrator verifies that a file downloaded from a vendor matches the SHA-256 value published on the vendor's website. Which element of the CIA triad does this check support?","a":["Confidentiality","Integrity","Accountability","Availability"],"c":1,"e":"Comparing hashes confirms the file has not been altered, which supports integrity. Hashing does not hide content, so it does not provide confidentiality. Availability concerns access to systems and data when needed. Accountability is part of AAA and relates to tracing actions to users, not to file tampering."},{"id":"S012","o":"1.2","d":1,"q":"A security team deploys a server with no legitimate business purpose that is configured to look like a vulnerable database. Any connection to it triggers an alert. What is this server called?","a":["Bastion host","Jump server","Honeypot","Sinkhole"],"c":2,"e":"A honeypot is a decoy system intended to attract attackers so their activity can be detected and studied. A jump server is a hardened host used by administrators to reach other systems. A bastion host is a hardened system exposed to untrusted networks that performs a real function. A sinkhole redirects malicious traffic, typically DNS, to a controlled destination."},{"id":"S013","o":"1.2","d":1,"q":"An auditor compares the organization's current security controls against the requirements of ISO 27001 to identify what is missing before a certification audit. What activity is the auditor performing?","a":["Business impact analysis","Tabletop exercise","Gap analysis","Penetration test"],"c":2,"e":"A gap analysis compares the current state with a desired standard or framework to identify deficiencies. A penetration test actively attempts to exploit weaknesses. A business impact analysis determines the effect of disruption on business functions. A tabletop exercise is a discussion-based walkthrough of an incident scenario."},{"id":"S014","o":"1.2","d":1,"q":"A user logs in with a username and password, the system checks the credentials, and the user is then allowed to read but not modify a shared folder. All actions are written to a log. Which part of this process is represented by the read only permission?","a":["Accounting","Authentication","Authorization","Identification"],"c":2,"e":"Authorization determines what an authenticated user is permitted to do, such as read but not write. Authentication verifies that the user is who they claim to be by checking credentials. Accounting records actions in logs. Identification is the claim of identity, such as entering a username."},{"id":"S015","o":"1.2","d":1,"q":"To reduce tailgating into a server room, a company installs a small enclosed space with two interlocking doors, where the second door opens only after the first one closes. What is this control called?","a":["Turnstile badge reader","Access control vestibule","Bollard","Security fence"],"c":1,"e":"An access control vestibule, sometimes called a mantrap, uses two interlocking doors so only one person passes at a time, preventing tailgating. Bollards stop vehicles, not people. A turnstile limits passage rate but does not create an enclosed interlocking space. A fence protects a perimeter and does not address tailgating at an interior door."},{"id":"S016","o":"1.2","d":1,"q":"A security engineer places fake AWS access keys in a code repository. If anyone attempts to use the keys, an alert is generated. What deception technique is this?","a":["DNS sinkhole","Canary deployment","Honeynet","Honeytoken"],"c":3,"e":"A honeytoken is a piece of fake data, such as a credential, that has no legitimate use and triggers an alert when used. A honeynet is a network of decoy systems. A DNS sinkhole redirects malicious domain lookups. A canary deployment is a software release strategy, not a deception technique."},{"id":"S017","o":"1.2","d":1,"q":"A hospital's patient portal is offline for six hours because of a failed storage controller, although no data was lost or exposed. Which security principle was MOST directly affected?","a":["Availability","Non-repudiation","Confidentiality","Integrity"],"c":0,"e":"Availability ensures that systems and data are accessible to authorized users when needed; an outage directly impacts it. Integrity was not affected because no data was altered. Confidentiality was not affected because nothing was disclosed. Non-repudiation relates to proof of origin of actions or messages."},{"id":"S018","o":"1.2","d":1,"q":"In a zero trust model, which component sits in the data plane and actually allows or blocks the traffic between a subject and a resource based on instructions it receives?","a":["Policy engine","Policy administrator","Threat intelligence feed","Policy enforcement point"],"c":3,"e":"The policy enforcement point is in the data plane and allows, monitors, or terminates the connection. The policy administrator, in the control plane, communicates the decision to the enforcement point. The policy engine makes the decision. A threat intelligence feed is an input to the decision process, not an enforcement mechanism."},{"id":"S019","o":"1.3","d":1,"q":"A developer wants to apply an emergency patch to a production database server at 2 PM on a weekday. The change process requires approval from a specific group before implementation. Which group typically reviews and approves such changes?","a":["Data protection officer","Internal audit committee","Change advisory board","Incident response team"],"c":2,"e":"The change advisory board evaluates proposed changes, their risk and impact, and approves or rejects them. The incident response team handles security incidents, not routine change approval. Internal audit evaluates controls after the fact rather than approving individual changes. A data protection officer oversees privacy compliance and does not approve technical changes."},{"id":"S020","o":"1.3","d":1,"q":"Before approving a firewall rule change, the change manager asks the requester to document what will happen if the change causes an outage and how the original configuration will be restored. What is the manager requesting?","a":["A backout plan","An impact analysis","A test result","A maintenance window"],"c":0,"e":"A backout plan describes how to reverse a change and return to the previous state if something goes wrong. An impact analysis assesses what the change will affect and how, but it does not define restoration steps. A maintenance window is the scheduled time for the change. A test result shows how the change behaved in a test environment."},{"id":"S021","o":"1.3","d":1,"q":"After a new certificate is installed on a load balancer, several internal applications fail because they were pinned to the old certificate. Which change management activity would MOST likely have prevented this problem?","a":["Updating the network diagram after the change","Scheduling the change outside business hours","Identifying dependencies before implementation","Obtaining approval from the asset owner"],"c":2,"e":"Identifying dependencies reveals which applications rely on the component being changed, such as pinned certificates, so they can be addressed in advance. Scheduling outside business hours limits user impact but would not prevent the failure. Updating diagrams is a documentation step after the change. Owner approval confirms authorization but does not uncover technical dependencies."},{"id":"S022","o":"1.3","d":1,"q":"A change to an application's configuration file requires the service to be restarted. Which consideration is MOST important to include in the change plan?","a":["Number of users with administrator rights","The license cost of the application","Expected downtime and service restart impact","Encryption strength of the configuration file"],"c":2,"e":"Service restarts cause downtime, so the plan must account for the outage and its effect on users and dependent systems. License cost is a procurement matter. Encryption of the configuration file is a separate security concern unrelated to the restart. The number of administrators does not affect the operational impact of the restart."},{"id":"S023","o":"1.3","d":1,"q":"Following a major infrastructure change, the security team updates the firewall rule documentation, network diagrams, and the configuration management database. Why is this step important?","a":["It is required to obtain the original change approval","Accurate documentation supports future changes and incident response","It replaces the need for a backout plan","It automatically detects unauthorized changes"],"c":1,"e":"Keeping documentation current ensures future changes, troubleshooting, and incident response are based on the real state of the environment. Approval happens before implementation, not after. Documentation does not replace a backout plan, which is needed in case the change fails. Documentation alone does not detect unauthorized changes; that requires monitoring or file integrity tools."},{"id":"S024","o":"1.3","d":1,"q":"A company tracks every version of its server configuration templates so it can identify who changed what and return to an earlier template if needed. Which practice is the company using?","a":["Allow listing","Data masking","Load balancing","Version control"],"c":3,"e":"Version control tracks changes to files over time, records who made each change, and allows rollback to previous versions. Allow listing restricts which applications can run. Data masking hides sensitive values. Load balancing distributes traffic across servers."},{"id":"S025","o":"1.4","d":1,"q":"A company needs to encrypt large volumes of backup data quickly before sending it to cloud storage. Which type of encryption is MOST appropriate for the bulk data?","a":["Digital signatures with ECDSA","Hashing with SHA-256","Asymmetric encryption such as RSA","Symmetric encryption such as AES"],"c":3,"e":"Symmetric algorithms like AES are fast and efficient for encrypting large amounts of data. Asymmetric encryption is much slower and is typically used to exchange keys, not to encrypt bulk data. Hashing is one-way and cannot be reversed to recover the data. Digital signatures provide integrity and non-repudiation, not confidentiality."},{"id":"S026","o":"1.4","d":1,"q":"A security architect wants to prevent attackers from using precomputed rainbow tables against stolen password hashes. What should be added before hashing each password?","a":["A digital certificate","A longer key escrow period","A unique random salt","A symmetric key"],"c":2,"e":"Adding a unique random salt to each password before hashing makes precomputed rainbow tables ineffective, because each hash would require its own table. Digital certificates bind public keys to identities and are unrelated to password storage. Encrypting passwords with a symmetric key is reversible and weaker than salted hashing. Key escrow concerns key recovery, not password hashes."},{"id":"S027","o":"1.4","d":1,"q":"Alice wants to send Bob a confidential message using asymmetric encryption so that only Bob can read it. Which key should Alice use to encrypt the message?","a":["Alice's private key","Alice's public key","Bob's public key","Bob's private key"],"c":2,"e":"Encrypting with the recipient's public key ensures only the recipient, who holds the matching private key, can decrypt the message. Alice never has access to Bob's private key. Encrypting with Alice's private key creates a signature that anyone with her public key can verify, so it gives no confidentiality. Encrypting with Alice's public key would mean only Alice could decrypt it."},{"id":"S028","o":"1.4","d":1,"q":"A web browser reports that a site's certificate has been revoked. Which mechanism allows the browser to check revocation status in real time for that single certificate instead of downloading a full list?","a":["Key escrow","CSR","OCSP","CRL"],"c":2,"e":"The Online Certificate Status Protocol lets a client query the status of a specific certificate in real time. A certificate revocation list is a complete list that must be downloaded and can be out of date. A certificate signing request is used to request a new certificate. Key escrow stores keys with a third party for recovery."},{"id":"S029","o":"1.4","d":1,"q":"A company stores encryption keys for its database servers in dedicated tamper-resistant hardware that performs cryptographic operations without exposing the keys. Which device is being used?","a":["Secure enclave on a mobile phone","Trusted Platform Module","Self-encrypting drive","Hardware security module"],"c":3,"e":"A hardware security module is a dedicated, tamper-resistant appliance that generates, stores, and uses keys for servers and applications at scale. A TPM is a chip on a single motherboard used mainly for platform integrity and local key storage. A self-encrypting drive encrypts its own contents but is not a key management device for database servers. A secure enclave protects keys on a single device such as a phone."},{"id":"S030","o":"1.4","d":1,"q":"A developer needs to use real customer records in a test environment but must ensure that card numbers cannot be recovered by testers. The original values must remain retrievable by the payment system through a secure lookup. Which technique BEST meets these requirements?","a":["Steganography","Tokenization","Data masking","Hashing"],"c":1,"e":"Tokenization replaces sensitive values with tokens and keeps the mapping in a secure vault, so the authorized payment system can retrieve the original. Hashing is one-way, so the original values could not be retrieved. Masking hides part of the data for display but typically is not reversible through a lookup. Steganography hides data inside other data and does not address this requirement."},{"id":"S031","o":"1.4","d":1,"q":"An organization wants a single certificate that will secure www.example.com, mail.example.com, and shop.example.com, and any future subdomains of example.com. Which certificate type is MOST appropriate?","a":["Root certificate","Wildcard certificate","Self-signed certificate","Code signing certificate"],"c":1,"e":"A wildcard certificate for *.example.com covers all first-level subdomains, including future ones. A self-signed certificate is not trusted by external clients. A code signing certificate is used to sign software, not secure websites. A root certificate belongs to a certificate authority and is used to sign other certificates."},{"id":"S032","o":"1.4","d":1,"q":"A laptop is stolen from an employee's car. The company is not concerned about data exposure because all data on the drive is protected even when the device is powered off. Which control provides this protection?","a":["File integrity monitoring","Full disk encryption","Remote wipe","Transport encryption"],"c":1,"e":"Full disk encryption protects data at rest, so a powered off laptop cannot be read without the key. Transport encryption protects data in transit over a network. File integrity monitoring detects changes to files and does not prevent reading them. Remote wipe requires the device to connect to a network and may never execute, so it does not guarantee protection."},{"id":"S033","o":"1.4","d":1,"q":"Two parties need to agree on a shared secret key over an untrusted network without ever sending the key itself. Which method allows this?","a":["AES-256 encryption","SHA-256 hashing","Out-of-band key delivery by courier","Diffie-Hellman key exchange"],"c":3,"e":"Diffie-Hellman lets two parties derive the same shared secret over an insecure channel without transmitting it. Hashing does not create shared keys. Delivery by courier is an out-of-band method that sends the key physically rather than establishing it over the network. AES is a symmetric cipher that requires the key to already be shared."},{"id":"S034","o":"1.4","d":1,"q":"A software vendor wants customers to be able to verify that an installer was published by the vendor and has not been modified since release. What should the vendor do?","a":["Host the installer on a server with TLS","Compress the installer and publish a file size","Encrypt the installer with AES","Digitally sign the installer with a code signing certificate"],"c":3,"e":"Code signing combines a hash with the vendor's private key, allowing users to verify both origin and integrity. Encrypting with AES protects confidentiality but does not prove origin. File size is easily matched by a modified file. TLS protects the download in transit but does not prove the file itself was published unaltered by the vendor."},{"id":"S035","o":"1.4","d":1,"q":"A certificate authority's root key is kept on an offline system, and a separate subordinate CA issues certificates to users and servers. What is the PRIMARY benefit of this design?","a":["Certificates can be issued without validation","Revocation lists are no longer required","Clients no longer need to trust the root","Compromise of the issuing CA does not expose the root key"],"c":3,"e":"Keeping the root CA offline protects its key; if the online intermediate is compromised, it can be revoked and replaced without rebuilding the entire trust chain. Validation is still required for issuance. Revocation lists or OCSP are still required. Clients still trust the root because the chain of trust ends there."},{"id":"S036","o":"1.4","d":1,"q":"A blockchain-based system records transactions in a distributed ledger. Which property of the ledger makes it difficult for an attacker to alter a past transaction without detection?","a":["Each block is encrypted with a symmetric key","Transactions are compressed before storage","The ledger is stored by a single trusted authority","Each block contains the hash of the previous block"],"c":3,"e":"Chaining blocks through hashes means modifying any earlier block changes its hash and breaks every subsequent link, making tampering evident. Blocks are not inherently encrypted. A blockchain is decentralized, not held by one authority. Compression has no effect on tamper resistance."},{"id":"S037","o":"2.1","d":2,"q":"A group with extensive funding and custom zero-day exploits maintains covert access to a defense contractor's network for over a year while exfiltrating engineering designs. Which threat actor is MOST likely responsible?","a":["Unskilled attacker","Nation-state","Hacktivist","Insider threat"],"c":1,"e":"Long-term covert access, custom zero-days, and theft of defense intellectual property indicate a well-resourced nation-state actor conducting espionage. Hacktivists usually seek publicity for a cause through defacement or leaks. Unskilled attackers rely on existing tools and lack the resources for sustained operations. An insider threat would already have legitimate access and would not need persistent covert footholds."},{"id":"S038","o":"2.1","d":2,"q":"A group defaces the website of an energy company and posts messages protesting the company's environmental record. No ransom is demanded and no data is sold. What is the MOST likely motivation?","a":["Financial gain","Philosophical or political beliefs","Espionage","Service disruption for blackmail"],"c":1,"e":"Defacement with protest messages and no financial demand points to a hacktivist driven by political or philosophical beliefs. Financial gain would involve ransom or data sales. Espionage aims to quietly steal information, not publicly announce the attack. Blackmail would include a demand in exchange for stopping the disruption."},{"id":"S039","o":"2.1","d":2,"q":"A disgruntled database administrator who was passed over for promotion copies the customer list before resigning and joins a competitor. Which threat actor type does this describe?","a":["Shadow IT","Insider threat","Organized crime","Nation-state"],"c":1,"e":"An insider threat is a current or former employee who misuses legitimate access, often motivated by revenge or financial gain. Organized crime groups are external and operate for profit at scale. Shadow IT refers to unauthorized systems or services used by staff, not intentional data theft. A nation-state is a government-sponsored external actor."},{"id":"S040","o":"2.1","d":2,"q":"A marketing team subscribes to an unapproved file sharing service and uploads campaign files containing customer contact data, bypassing IT procurement. What is this an example of?","a":["Hacktivism","Supply chain compromise","Shadow IT","Advanced persistent threat"],"c":2,"e":"Shadow IT is the use of technology or services without the approval of the IT department, which introduces unmanaged risk. Hacktivism involves attacks for ideological reasons. An advanced persistent threat is a sophisticated long-term intrusion. A supply chain compromise involves an attacker targeting a vendor or product used by the organization."},{"id":"S041","o":"2.1","d":2,"q":"A teenager downloads a ready-made DDoS tool from a forum and uses it against a gaming server after losing a match. Which attribute BEST describes this threat actor?","a":["High sophistication with state funding","Low sophistication with limited resources","Organized group with financial motivation","Internal actor with privileged access"],"c":1,"e":"Using a prebuilt tool out of personal frustration reflects an unskilled attacker with low sophistication and minimal resources. State funding and high sophistication describe nation-state actors. The teenager is external, not an insider. There is no organized structure or profit motive."},{"id":"S042","o":"2.1","d":2,"q":"A ransomware gang operates with a help desk, affiliates, and negotiators, and splits ransom payments between developers and affiliates. Which threat actor category BEST fits this group?","a":["Organized crime","Unskilled attacker","Insider threat","Hacktivist"],"c":0,"e":"Organized crime groups run structured, profit-driven operations such as ransomware as a service with affiliates and support staff. Hacktivists are motivated by ideology rather than ransom. Insiders work within the targeted organization. Unskilled attackers lack the organization and resources described."},{"id":"S043","o":"2.1","d":2,"q":"Which motivation is MOST closely associated with an attacker who deletes data and destroys systems to cause maximum operational damage, without demanding payment?","a":["Data exfiltration for resale","Disruption or chaos","Financial gain","Ethical disclosure"],"c":1,"e":"Destroying systems without any demand indicates the goal is disruption or chaos. Financial gain would involve extortion or theft for sale. Exfiltrating data for resale preserves the data rather than destroying it. Ethical disclosure involves responsibly reporting vulnerabilities, not causing damage."},{"id":"S044","o":"2.1","d":2,"q":"A security researcher discovers a vulnerability in a vendor product, reports it privately to the vendor, and waits for a patch before publishing details. How is this researcher BEST described?","a":["Insider threat seeking revenge","Unauthorized attacker seeking financial gain","Hacktivist seeking publicity","Ethical hacker using responsible disclosure"],"c":3,"e":"Reporting privately and waiting for a fix is responsible disclosure, consistent with ethical intent. A financially motivated attacker would exploit or sell the vulnerability. An insider seeking revenge would misuse internal access. A hacktivist would publish to embarrass the vendor rather than coordinate a fix."},{"id":"S045","o":"2.1","d":2,"q":"An attacker breaches a hospital network and threatens to publish patient records unless a payment is made, even though no files were encrypted. Which motivation is MOST evident?","a":["Blackmail","Revenge","Philosophical beliefs","Espionage"],"c":0,"e":"Threatening to release stolen data unless paid is extortion, commonly categorized as blackmail. Espionage would quietly retain data for intelligence purposes. Philosophical motivation would focus on a cause rather than payment. Revenge would be personal and usually not structured around a payment demand."},{"id":"S046","o":"2.1","d":2,"q":"A competitor hires an outside group to steal a rival's product formulas and pricing strategy. Which motivation BEST describes the competitor's intent?","a":["Corporate espionage","Ethical testing","Political activism","War"],"c":0,"e":"Stealing a rival's proprietary information for business advantage is corporate espionage. Political activism concerns causes, not trade secrets. War relates to state conflict and critical infrastructure. Ethical testing is authorized work, not theft."},{"id":"S047","o":"2.1","d":2,"q":"Which characteristic distinguishes an advanced persistent threat from most other attack types?","a":["Automated scanning of random internet hosts","Long-term stealthy presence focused on a specific target","Use of publicly available exploit kits only","Short attacks designed to be immediately visible"],"c":1,"e":"An APT is defined by sustained, covert access focused on a chosen target, often for espionage. APTs commonly use custom tools rather than only public exploit kits. They are designed to avoid detection rather than be visible. Random internet scanning is opportunistic and not targeted."},{"id":"S048","o":"2.1","d":2,"q":"An employee clicks a malicious link in good faith, which leads to malware infecting the network. How is this employee BEST classified from a threat perspective?","a":["Hacktivist","Nation-state agent","Malicious insider","Unintentional insider threat"],"c":3,"e":"An employee who causes harm through carelessness or deception without malicious intent is an unintentional insider threat. A malicious insider acts deliberately. A hacktivist is an external actor with ideological motives. A nation-state agent operates on behalf of a government."},{"id":"S049","o":"2.2","d":2,"q":"Employees receive text messages appearing to come from the company's parcel provider, asking them to click a link to reschedule a delivery. Which attack vector is being used?","a":["Watering hole","Smishing","Vishing","Whaling"],"c":1,"e":"Smishing is phishing delivered through SMS text messages. Vishing uses voice calls. Whaling targets senior executives specifically. A watering hole attack compromises a website frequented by the target group."},{"id":"S050","o":"2.2","d":2,"q":"Attackers compromise a popular industry forum that engineers at a target company regularly visit and inject malicious code into its pages. What type of attack is this?","a":["Brand impersonation","Typosquatting","Watering hole","Pretexting"],"c":2,"e":"A watering hole attack infects a site the targets are known to visit, rather than attacking them directly. Typosquatting registers misspelled domains to catch users who mistype addresses. Pretexting is building a fabricated scenario to manipulate a victim. Brand impersonation imitates a known company to deceive people."},{"id":"S051","o":"2.2","d":2,"q":"A user mistypes the company's payroll portal address and lands on a lookalike site that collects credentials. The attacker registered a domain differing by one letter. What technique did the attacker use?","a":["Typosquatting","Pharming through DNS poisoning","Business email compromise","Shoulder surfing"],"c":0,"e":"Typosquatting relies on registering domains similar to legitimate ones to exploit typing mistakes. DNS poisoning would redirect users even when they type the correct address. Business email compromise uses a compromised or spoofed email account for fraud. Shoulder surfing is observing someone's screen or keystrokes."},{"id":"S052","o":"2.2","d":2,"q":"A caller claims to be from the IT help desk, says the user's mailbox is about to be deleted due to an audit, and asks for the user's MFA code to prevent it. Which social engineering principles are MOST evident?","a":["Reciprocity and liking","Familiarity and trust built over time","Authority and urgency","Scarcity and consensus"],"c":2,"e":"The attacker claims an authoritative role, the help desk, and creates time pressure with an imminent deletion, which combines authority and urgency. Scarcity relates to limited availability of something desirable, and consensus to social proof. There is no long-term relationship that would build familiarity. Reciprocity involves giving something to create an obligation."},{"id":"S053","o":"2.2","d":2,"q":"A finance clerk receives an email that appears to come from the CFO's real account asking for an urgent wire transfer to a new supplier. Investigation shows the CFO's mailbox had been compromised. What type of attack is this?","a":["Disinformation campaign","Smishing","Business email compromise","Spear phishing using a spoofed domain"],"c":2,"e":"Business email compromise uses a legitimate but compromised business account to request fraudulent payments. Spear phishing with a spoofed domain would come from a lookalike address, not the real mailbox. Smishing uses SMS. Disinformation spreads false information to influence opinion rather than to obtain payments."},{"id":"S054","o":"2.2","d":2,"q":"A security team finds that a USB drive labeled 'Salary Review 2026' was left in the parking lot and later plugged into a workstation, launching malware. Which attack vector does this represent?","a":["Removable media baiting","Vishing","Watering hole","Bluetooth bluejacking"],"c":0,"e":"Leaving infected removable media for victims to find and use is a baiting attack via removable media. Bluejacking sends unsolicited messages over Bluetooth. A watering hole compromises a frequently visited website. Vishing uses phone calls."},{"id":"S055","o":"2.2","d":2,"q":"A company's guest Wi-Fi uses the same SSID and password printed on posters in the lobby, and the network has access to internal printers. Which attack surface concern is MOST significant?","a":["Lack of a captive portal for guests","Use of WPA3-Personal instead of WPA2","Broadcasting the guest SSID","Lack of segmentation between guest and internal resources"],"c":3,"e":"Allowing guests to reach internal printers means anyone in the lobby can interact with internal devices, which is the main exposure. WPA3-Personal is stronger than WPA2 and is not a weakness. A captive portal adds terms acceptance or registration but would not stop guests reaching internal printers. Broadcasting the SSID has minimal security effect, since hidden SSIDs are easily discovered."},{"id":"S056","o":"2.2","d":2,"q":"An attacker contacts a newly hired employee on a professional networking site, claiming to be a recruiter, and over several weeks gathers details about internal tools before sending a malicious attachment. Which technique was used FIRST to gain the employee's cooperation?","a":["Tailgating","Pretexting","Credential stuffing","Typosquatting"],"c":1,"e":"Pretexting is building a believable invented story or role, here a recruiter, to gain trust and information. Typosquatting involves lookalike domains. Credential stuffing reuses leaked passwords against services. Tailgating is following someone into a secure physical area."},{"id":"S057","o":"2.2","d":2,"q":"An organization relies on a managed service provider that has remote administrative access to all of its servers. Attackers compromise the provider and use that access to deploy ransomware. Which threat vector was exploited?","a":["Supply chain through a service provider","Unsecured wireless network","Default credentials on IoT devices","Open service port on a web server"],"c":0,"e":"The attackers abused the trust relationship with an MSP, which is a supply chain vector. No wireless weakness is described. Default credentials on IoT devices are a separate issue. The attack used the provider's legitimate remote access rather than an exposed service port."},{"id":"S058","o":"2.2","d":2,"q":"A security review finds that several servers still run Telnet and FTP for administration. Why is this considered an attack surface concern?","a":["The protocols lack centralized logging support","The protocols cannot be used with jump servers","The protocols do not support IPv6","The protocols send credentials in cleartext"],"c":3,"e":"Telnet and FTP transmit usernames and passwords without encryption, so anyone able to capture traffic can read them. They can be used through jump servers, they work over IPv6, and their activity can be logged; none of these is the core weakness."},{"id":"S059","o":"2.2","d":2,"q":"An attacker sends a voicemail to an executive that sounds exactly like the CEO, created with AI voice cloning, instructing the executive to approve a confidential acquisition payment. Which attack type is this?","a":["Smishing","Vishing","Watering hole","Typosquatting"],"c":1,"e":"Using a voice channel and a cloned voice to impersonate an authority figure is vishing with impersonation. Smishing uses text messages. A watering hole compromises websites. Typosquatting exploits misspelled domains."},{"id":"S060","o":"2.2","d":2,"q":"Which of the following BEST reduces the attack surface of a newly deployed Linux server?","a":["Disabling unnecessary services and closing unused ports","Adding the server to multiple VLANs for redundancy","Installing a graphical desktop for easier administration","Enabling every logging level for all services"],"c":0,"e":"Removing unneeded services and ports directly reduces the number of entry points an attacker can use. A graphical desktop adds software and increases the attack surface. Verbose logging aids detection but does not shrink exposure. Connecting to multiple VLANs increases exposure."},{"id":"S061","o":"2.2","d":2,"q":"An attacker uses a fake social media account of a well-known software vendor to post a link to a malicious 'security update'. Which technique is MOST evident?","a":["Pharming via hosts file","Brand impersonation","Credential harvesting through SMS","Shoulder surfing"],"c":1,"e":"Pretending to be a trusted vendor to lure victims is brand impersonation. SMS is not involved. Shoulder surfing requires physically observing a victim. Pharming via hosts file modification would redirect a victim's traffic on their own machine."},{"id":"S062","o":"2.2","d":2,"q":"A company's IoT security cameras are reachable from the internet and still use the manufacturer's default admin password. Which threat vector does this create?","a":["Watering hole","Default credentials","Message-based phishing","Removable media"],"c":1,"e":"Devices exposed with factory default passwords can be accessed by anyone who knows the published credentials. Phishing involves deceiving users through messages. Removable media involves USB drives or similar. A watering hole compromises websites."},{"id":"S063","o":"2.2","d":2,"q":"A threat actor creates many fake news articles and social media posts claiming that a bank is insolvent, triggering customer withdrawals. What is this an example of?","a":["Pretexting a single employee","Business email compromise","Tailgating","Disinformation"],"c":3,"e":"Deliberately spreading false information to influence behavior is disinformation. Business email compromise targets payment processes through email accounts. Pretexting a single employee involves a crafted story for one victim. Tailgating is a physical entry technique."},{"id":"S064","o":"2.3","d":2,"q":"A web application concatenates user input directly into a database query. An attacker enters ' OR 1=1 -- into the login field and gains access. Which vulnerability was exploited?","a":["Buffer overflow","Race condition","Cross-site scripting","SQL injection"],"c":3,"e":"Inserting SQL syntax into input that is concatenated into a query is SQL injection. Cross-site scripting injects scripts into pages viewed by other users. A buffer overflow writes beyond allocated memory. A race condition exploits timing between operations."},{"id":"S065","o":"2.3","d":2,"q":"A forum allows users to post comments that are displayed to other visitors without encoding. An attacker posts a comment containing a script that steals session cookies from anyone who views it. Which vulnerability is this?","a":["Stored cross-site scripting","SQL injection","Directory traversal","Reflected cross-site scripting"],"c":0,"e":"Stored XSS saves the malicious script on the server so it runs for every visitor who views the content. Reflected XSS requires the victim to click a crafted link and is not persistently stored. SQL injection targets the database. Directory traversal accesses files outside the intended directory."},{"id":"S066","o":"2.3","d":2,"q":"A program checks whether a user has permission to a file and then opens it a few milliseconds later. An attacker swaps the file with a symbolic link to a protected file between the check and the open. What vulnerability is this?","a":["Integer overflow","Time-of-check to time-of-use race condition","Insecure direct object reference","Memory leak"],"c":1,"e":"A TOCTOU race condition exploits the gap between verifying a condition and using the resource. A memory leak is failure to release memory. An integer overflow occurs when a value exceeds its maximum size. An insecure direct object reference exposes objects by changing an identifier, without any timing element."},{"id":"S067","o":"2.3","d":2,"q":"An organization runs a server operating system that the vendor stopped supporting two years ago. What is the PRIMARY security concern?","a":["New vulnerabilities will not receive patches","The server will stop booting after support ends","Encryption is automatically disabled","Licenses will be revoked and data deleted"],"c":0,"e":"End of support means newly discovered vulnerabilities remain unpatched, leaving the system permanently exposed. The operating system continues to boot. Encryption is not automatically disabled. Licensing changes do not delete data."},{"id":"S068","o":"2.3","d":2,"q":"Researchers find that a smartphone user installed apps from a third-party website rather than the official store, bypassing the device's review process. Which mobile vulnerability does this describe?","a":["SIM cloning","Bluesnarfing","Sideloading","Jailbreaking"],"c":2,"e":"Sideloading is installing apps from sources outside the official store, bypassing vetting. Jailbreaking removes operating system restrictions altogether, which may enable sideloading but is a different action. SIM cloning duplicates a SIM card. Bluesnarfing steals data via Bluetooth."},{"id":"S069","o":"2.3","d":2,"q":"A cloud storage bucket containing customer invoices was configured to allow public read access by mistake. Which category of vulnerability is this?","a":["Firmware vulnerability","Misconfiguration","Zero-day","Cryptographic weakness"],"c":1,"e":"Incorrect settings that expose data are misconfigurations, one of the most common cloud vulnerabilities. A zero-day is an unknown flaw with no patch available. Firmware vulnerabilities exist in device-level software. A cryptographic weakness involves flawed algorithms or implementations."},{"id":"S070","o":"2.3","d":2,"q":"An attacker sends input longer than a program's allocated memory space, overwriting the return address on the stack and executing injected code. What vulnerability was exploited?","a":["Buffer overflow","Privilege creep","Cross-site request forgery","Session fixation"],"c":0,"e":"A buffer overflow writes data beyond a buffer's boundary, which can overwrite the return address and redirect execution. CSRF tricks a user's browser into sending unwanted requests. Privilege creep is the accumulation of unnecessary permissions. Session fixation forces a known session ID onto a user."},{"id":"S071","o":"2.3","d":2,"q":"Security analysts learn that attackers are exploiting a flaw in a widely used VPN appliance, and the vendor has not yet released a fix or advisory. How is this vulnerability BEST described?","a":["Misconfiguration","Zero-day","False positive","Legacy"],"c":1,"e":"A zero-day is a vulnerability exploited before the vendor has a fix available. Legacy refers to outdated systems no longer supported. Misconfiguration results from incorrect settings, not product flaws. A false positive is an incorrect alert, while this exploitation is real."},{"id":"S072","o":"2.3","d":2,"q":"A malicious update to an open-source library used by thousands of applications introduces a backdoor. Which type of vulnerability is MOST relevant?","a":["Physical vulnerability","Virtual machine escape","Supply chain","Weak cipher suite"],"c":2,"e":"Compromising a dependency distributed to many applications is a software supply chain vulnerability. Physical vulnerabilities concern access to hardware. VM escape involves breaking out of a virtual machine. Weak cipher suites concern encryption choices."},{"id":"S073","o":"2.3","d":2,"q":"An attacker running code in a guest virtual machine exploits a hypervisor flaw to access the memory of other guest VMs on the same host. What is this called?","a":["Rootkit installation on the host disk","Virtual machine escape","Jailbreaking","Resource reuse"],"c":1,"e":"VM escape occurs when code breaks out of the guest boundary to interact with the hypervisor or other guests. Resource reuse refers to data remnants in reallocated resources, not active exploitation of the hypervisor. Jailbreaking applies to mobile devices. Installing a rootkit on the host disk would be a consequence, not the vulnerability described."},{"id":"S074","o":"2.3","d":2,"q":"After a cloud VM is deleted, a new tenant's VM is allocated the same storage blocks and can recover fragments of the previous tenant's data. Which vulnerability is this?","a":["Directory traversal","Cross-site scripting","Memory injection","Resource reuse"],"c":3,"e":"Resource reuse occurs when storage or memory is reallocated without being properly cleared, exposing data to the next user. XSS is a web vulnerability. Directory traversal is navigating file paths beyond allowed directories. Memory injection inserts code into a running process."},{"id":"S075","o":"2.3","d":2,"q":"A URL such as https://app.example.com/files?name=../../etc/passwd returns the contents of the system password file. Which vulnerability is present?","a":["Cross-site request forgery","Server-side request forgery","Directory traversal","Replay attack"],"c":2,"e":"Using ../ sequences to reach files outside the intended directory is directory traversal. CSRF forges requests from a victim's browser. SSRF makes the server send requests to other systems. A replay attack resends captured valid data."},{"id":"S076","o":"2.3","d":2,"q":"An attacker modifies the firmware of a network switch so that it forwards copies of traffic to an external host, and the change persists across reboots. Which vulnerability category is MOST relevant?","a":["Application","Operating system","Web-based","Firmware"],"c":3,"e":"Persistent changes made to device firmware are a firmware vulnerability, and they survive reboots and often reimaging. Application vulnerabilities exist in software running on the device. Operating system vulnerabilities apply to the OS layer. Web-based vulnerabilities apply to web applications."},{"id":"S077","o":"2.3","d":2,"q":"A firmware routine stores the number of failed login attempts in a 16-bit unsigned variable. After 65,535 failures the counter wraps back to zero and the lockout never triggers, allowing unlimited guessing. Which vulnerability is this?","a":["Cross-site scripting","Memory leak","Integer overflow","Pointer dereference"],"c":2,"e":"An integer overflow occurs when a value exceeds the maximum the variable can hold and wraps around, here resetting the counter so the lockout logic fails. XSS concerns script injection. A memory leak is failure to free memory over time. A pointer dereference flaw involves accessing invalid memory addresses."},{"id":"S078","o":"2.4","d":2,"q":"Authentication logs show a single user account successfully logging in from London at 09:02 and from Singapore at 09:20 on the same day. Which indicator of compromise does this represent?","a":["Resource consumption","Missing logs","Impossible travel","Account lockout"],"c":2,"e":"Two logins from distant locations within a time window too short for physical travel is the impossible travel indicator, suggesting credential compromise. Account lockout would show failed attempts and blocked access. Resource consumption refers to abnormal CPU, memory, or bandwidth usage. Missing logs indicates gaps in logging, often from tampering."},{"id":"S079","o":"2.4","d":2,"q":"Over one hour, a web portal records a few failed login attempts each for thousands of different accounts, all using the same three common passwords. What type of attack is MOST likely occurring?","a":["Pass-the-hash","Brute force against a single account","Birthday attack","Password spraying"],"c":3,"e":"Password spraying tries a small number of common passwords across many accounts to avoid lockouts. A brute force attack would try many passwords against one account. Pass-the-hash reuses captured hashes rather than guessing passwords. A birthday attack targets hash collisions."},{"id":"S080","o":"2.4","d":2,"q":"Several users report that files on a shared drive now have a .locked extension, and a text file in each folder demands payment in cryptocurrency. Which type of malware is present?","a":["Logic bomb","Adware","Spyware","Ransomware"],"c":3,"e":"Encrypting files and demanding payment for the key is the defining behavior of ransomware. Spyware secretly gathers information. A logic bomb executes when a condition is met, and its payload is not necessarily extortion. Adware displays unwanted advertisements."},{"id":"S081","o":"2.4","d":2,"q":"Before leaving the company, a developer secretly planted a scheduled script that would delete production databases once their own account was disabled. The script ran two weeks after the developer left. What type of malicious code is this?","a":["Worm","Keylogger","Logic bomb","Trojan"],"c":2,"e":"A logic bomb is code that executes when a specific condition occurs, such as an account being disabled. A worm self-replicates across networks. A trojan disguises itself as legitimate software to get installed. A keylogger records keystrokes."},{"id":"S082","o":"2.4","d":2,"q":"A malware sample spreads across the network by exploiting an SMB vulnerability on unpatched hosts, without any user interaction. Which type of malware is this?","a":["Trojan","Rootkit","Worm","Virus"],"c":2,"e":"A worm self-propagates by exploiting vulnerabilities and does not require a user to run it. A virus needs a host file and user action to spread. A trojan relies on the user installing seemingly legitimate software. A rootkit hides malware and maintains privileged access but does not inherently spread."},{"id":"S083","o":"2.4","d":2,"q":"Antivirus scans of a server come back clean, yet network monitoring shows outbound connections to a known malicious IP. Investigators find that system tools have been modified to hide the malicious process. What is MOST likely installed?","a":["Potentially unwanted program","Rootkit","Bloatware","Adware"],"c":1,"e":"A rootkit operates with high privileges and alters system components to hide malicious processes, files, and connections from security tools. Adware shows advertisements and does not typically hide at this level. Bloatware is unnecessary preinstalled software. A potentially unwanted program is undesired but not stealthy malware."},{"id":"S084","o":"2.4","d":2,"q":"A SIEM shows that a workstation contacts the same external domain every 60 seconds with small, uniform HTTPS requests, even when no user is logged in. What does this MOST likely indicate?","a":["DNS cache poisoning","Normal software update checks","Command and control beaconing","A distributed denial of service attack"],"c":2,"e":"Regular, small, periodic connections to an external host regardless of user activity are characteristic of malware beaconing to a command and control server. Update checks are infrequent and go to known vendor domains. A DDoS involves massive traffic volumes. DNS cache poisoning corrupts name resolution and does not create periodic outbound traffic."},{"id":"S085","o":"2.4","d":2,"q":"Network monitoring shows an internal database server suddenly sending 40 GB of data to an external cloud storage provider at 3 AM, far above its normal baseline. Which indicator is MOST concerning?","a":["Blocked content by the web proxy","Concurrent session usage","Unusual outbound data volume","Out-of-cycle logging"],"c":2,"e":"An abnormal spike in outbound data from a server to an external destination at an unusual time suggests exfiltration. Blocked content indicates a control worked. Concurrent session usage refers to the same account logged in simultaneously in multiple places. Out-of-cycle logging refers to logs generated at unusual times, but the core concern here is the volume transferred."},{"id":"S086","o":"2.4","d":2,"q":"A user's browser session is hijacked because an attacker on the same café Wi-Fi intercepted traffic between the user and the access point and relayed it after reading the session cookie. Which attack occurred?","a":["Password spraying","DNS amplification","Replay of a captured Kerberos ticket","On-path attack"],"c":3,"e":"An on-path attack places the attacker between two communicating parties to intercept and potentially alter traffic. A Kerberos ticket replay reuses captured authentication tickets inside an Active Directory environment. DNS amplification is a DDoS technique. Password spraying guesses common passwords across many accounts."},{"id":"S087","o":"2.4","d":2,"q":"An attacker sends small DNS queries with a spoofed source IP address of a victim to many open resolvers, causing large responses to flood the victim. What type of attack is this?","a":["DNS tunneling","DNS amplification","SYN scan","Domain hijacking"],"c":1,"e":"Using spoofed requests to open resolvers that return large responses to the victim is a DNS amplification DDoS. DNS tunneling hides data inside DNS traffic for covert communication. Domain hijacking takes control of a domain registration. A SYN scan discovers open ports."},{"id":"S088","o":"2.4","d":2,"q":"A security analyst sees that an attacker obtained NTLM hashes from a compromised workstation and used them to authenticate to a file server without cracking the passwords. Which attack is this?","a":["Pass-the-hash","Downgrade attack","Rainbow table attack","Credential stuffing"],"c":0,"e":"Pass-the-hash uses the captured hash directly for authentication, so cracking is not needed. A rainbow table attack attempts to reverse hashes into passwords. Credential stuffing uses plaintext username and password pairs leaked from other breaches. A downgrade attack forces weaker protocol versions."},{"id":"S089","o":"2.4","d":2,"q":"Shortly after a data breach at a popular retailer, many of a company's employees experience login attempts using their exact email addresses and passwords from the retailer's leak. What type of attack is this?","a":["Phishing","Credential stuffing","Brute force","Password spraying"],"c":1,"e":"Credential stuffing uses username and password pairs leaked from other services, exploiting password reuse. Password spraying uses a few common passwords across many accounts. Brute force tries many possible passwords. Phishing tricks users into submitting credentials directly."},{"id":"S090","o":"2.4","d":2,"q":"Badge access logs show an employee entering the data center at 2 AM, but the employee was on a flight at that time. The badge was not reported lost. What is the MOST likely explanation?","a":["The badge was cloned","Tailgating by a visitor","Environmental sensor failure","A brute force attack on the badge reader"],"c":0,"e":"A badge used while its owner was demonstrably elsewhere, without being reported lost, suggests the RFID credential was cloned. Tailgating would not produce a log entry for the employee's badge. Brute forcing badge readers is not a typical attack. Environmental sensors do not record access events."},{"id":"S091","o":"2.4","d":2,"q":"An attacker captures a valid authentication message on the network and resends it later to gain access to a system. Which attack is this, and what helps prevent it?","a":["Collision attack, prevented by shorter hashes","Privilege escalation, prevented by account lockout","Downgrade attack, prevented by disabling TLS","Replay attack, prevented by timestamps or nonces"],"c":3,"e":"A replay attack retransmits captured valid data, and timestamps, nonces, or session tokens make old messages invalid. A downgrade attack forces weaker protocols and disabling TLS would worsen security. Collision attacks are mitigated by stronger, not shorter, hashes. Privilege escalation is unrelated to resending captured authentication messages."},{"id":"S092","o":"2.5","d":2,"q":"An organization wants to prevent a compromised workstation in the accounting department from reaching the engineering servers. Which mitigation is MOST effective?","a":["Full disk encryption","Network segmentation","Password complexity policy","Data loss prevention on email"],"c":1,"e":"Segmentation separates networks so compromise in one area cannot easily reach another. Full disk encryption protects data at rest on a device. Password complexity makes guessing harder but does not limit lateral movement. Email DLP prevents sensitive data leaving through email."},{"id":"S093","o":"2.5","d":2,"q":"A company wants to ensure that only approved applications can run on its point-of-sale terminals. Which technique BEST achieves this?","a":["Antivirus signature updates","Patch management","Host-based firewall","Application allow list"],"c":3,"e":"An allow list permits only explicitly approved software to execute, which suits fixed-purpose devices like POS terminals. Antivirus detects known malware but allows unknown software to run. A host firewall controls network traffic, not which programs execute. Patching fixes vulnerabilities but does not restrict which applications run."},{"id":"S094","o":"2.5","d":2,"q":"After a security review, administrators remove local administrator rights from all standard user accounts. Which principle does this enforce?","a":["Separation of duties","Least privilege","Defense in depth","Job rotation"],"c":1,"e":"Least privilege gives users only the permissions required for their job. Separation of duties splits a critical task among several people. Job rotation moves staff between roles periodically. Defense in depth uses multiple layers of controls; removing admin rights is one layer but the principle being enforced is least privilege."},{"id":"S095","o":"2.5","d":2,"q":"A new set of servers is deployed and the security team removes unnecessary software, disables unused services, changes default passwords, and applies a CIS benchmark. What process is this?","a":["Isolation","Hardening","Decommissioning","Sandboxing"],"c":1,"e":"Hardening reduces a system's attack surface through secure configuration, often guided by benchmarks. Sandboxing runs untrusted code in a restricted environment. Decommissioning is retiring a system. Isolation separates a system from others, typically during an incident."},{"id":"S096","o":"2.5","d":2,"q":"During an active malware outbreak, a security analyst disconnects an infected laptop from the network but leaves it powered on. What mitigation is being applied?","a":["Monitoring","Patching","Isolation","Encryption"],"c":2,"e":"Isolation removes the infected device from the network to stop spread while preserving its state for investigation. Encryption protects data confidentiality. Patching fixes vulnerabilities but does not contain an active infection. Monitoring observes activity but does not stop spread."},{"id":"S097","o":"2.5","d":2,"q":"Which mitigation BEST ensures that a vulnerability in a web server cannot be used to directly access the internal file server?","a":["Increasing the web server's RAM","Screened subnet with restrictive ACLs","Changing the web server's hostname regularly","Installing a newer web browser on the server"],"c":1,"e":"A screened subnet with access control lists limits what a compromised web server can reach internally. More RAM affects performance. A browser on the server is irrelevant and adds attack surface. Changing hostnames does not prevent network access."},{"id":"S098","o":"2.5","d":2,"q":"A company configures its domain controllers to send all security logs to a central system that alerts on suspicious activity. Which mitigation technique is this?","a":["Monitoring","Segmentation","Least privilege","Encryption"],"c":0,"e":"Collecting and analyzing logs to detect suspicious activity is monitoring. Segmentation divides networks. Encryption protects confidentiality. Least privilege limits permissions."},{"id":"S099","o":"2.5","d":2,"q":"To prevent attackers from accessing sensitive data if a database backup tape is lost in transit, which mitigation should be applied?","a":["Configure port security","Apply an application allow list","Encrypt the backup data","Enable account lockout"],"c":2,"e":"Encrypting backups protects data confidentiality if media is lost or stolen. Application allow lists control software execution. Port security restricts devices on switch ports. Account lockout protects against password guessing."},{"id":"S100","o":"2.5","d":2,"q":"An organization deploys endpoint detection and response software that can automatically kill malicious processes and quarantine files. What is the PRIMARY benefit over traditional signature-based antivirus?","a":["Behavior-based detection and response","Elimination of the need for patching","Lower licensing cost","Replacement of network firewalls"],"c":0,"e":"EDR analyzes behavior and can detect and respond to threats without known signatures, such as fileless attacks. Cost is not its defining benefit. Patching is still required. EDR protects endpoints and does not replace network firewalls."},{"id":"S101","o":"2.5","d":2,"q":"A company has finished using an old file server and wants to ensure no residual data can be recovered. What is the BEST mitigation?","a":["Disable the server's antivirus","Change the administrator password","Sanitize the storage when decommissioning","Remove the server from DNS"],"c":2,"e":"Proper decommissioning includes sanitizing or destroying storage so data cannot be recovered. Changing passwords does not remove data. Removing DNS records only hides the server. Disabling antivirus increases risk."},{"id":"S102","o":"2.5","d":2,"q":"A security engineer configures user accounts so that a payment can be created by one employee but must be approved by a different employee. Which mitigation principle is applied?","a":["Mandatory vacation","Least privilege","Separation of duties","Implicit deny"],"c":2,"e":"Separation of duties divides a sensitive process between different people to prevent fraud by a single individual. Least privilege limits permissions but does not require two people. Mandatory vacation helps detect ongoing fraud. Implicit deny blocks anything not explicitly allowed."},{"id":"S103","o":"3.1","d":3,"q":"A company moves its email to a SaaS provider. Under the shared responsibility model, which responsibility remains with the company?","a":["Managing user accounts and access permissions","Patching the provider's mail server operating system","Maintaining the provider's hypervisor","Physical security of the provider's data center"],"c":0,"e":"In SaaS, the customer remains responsible for its data, identities, and access configuration. Patching the underlying OS, physical data center security, and hypervisor maintenance are all handled by the provider in a SaaS model."},{"id":"S104","o":"3.1","d":3,"q":"A development team deploys virtual machines in a cloud environment and is responsible for patching the guest operating systems. Which cloud service model are they using?","a":["Software as a Service","Function as a Service","Infrastructure as a Service","Platform as a Service"],"c":2,"e":"In IaaS, the customer manages the guest OS, applications, and data, while the provider manages the physical infrastructure and virtualization layer. In SaaS the provider manages everything except data and access. In PaaS the provider manages the OS and runtime. In serverless or FaaS, the provider manages the execution environment."},{"id":"S105","o":"3.1","d":3,"q":"An architect wants to define network and server configurations in version-controlled files so that environments can be recreated consistently and reviewed before deployment. What approach should be used?","a":["Thin client virtualization","Air-gapped deployment","Infrastructure as code","Manual baseline documentation"],"c":2,"e":"Infrastructure as code defines infrastructure in machine-readable files, enabling consistent, repeatable, and reviewable deployments. Manual documentation is error prone and not executable. Air gapping isolates networks physically. Thin client virtualization delivers desktops from central servers."},{"id":"S106","o":"3.1","d":3,"q":"A plant uses SCADA systems to control water treatment pumps. Which security approach is MOST appropriate for these systems?","a":["Apply automatic patches immediately as released","Allow employees to access them via personal devices","Expose them through a public API for monitoring","Isolate them from the corporate network and the internet"],"c":3,"e":"Industrial control systems are often fragile and safety critical, so isolation and strict segmentation are key. Automatic patching can disrupt operations and must be tested first. Exposing them publicly greatly increases risk. Personal devices introduce unmanaged risk to critical systems."},{"id":"S107","o":"3.1","d":3,"q":"A company runs microservices in containers. A container is compromised, but the attacker cannot access other containers on the same host. Which property helped limit the impact?","a":["Containers share a single kernel","Process and namespace isolation between containers","Containers use full hardware virtualization","Containers run on a public blockchain"],"c":1,"e":"Containers use namespace and control group isolation to separate processes, limiting the blast radius. Sharing a kernel is actually a weakness that could enable escape. Containers do not use full hardware virtualization like VMs. Blockchain is irrelevant to container isolation."},{"id":"S108","o":"3.1","d":3,"q":"A serverless function is triggered by file uploads and processes images. Which security concern remains the customer's responsibility?","a":["Securing the function code and its permissions","Patching the underlying servers","Maintaining the runtime environment's operating system","Securing physical hosts"],"c":0,"e":"In serverless computing, the customer is responsible for the code and the permissions granted to the function. The provider manages servers, the runtime OS, and physical hosts."},{"id":"S109","o":"3.1","d":3,"q":"Which characteristic of embedded systems MOST complicates securing them?","a":["Use of general-purpose operating systems","Frequent vendor updates","Constrained resources and limited patching","High processing power"],"c":2,"e":"Embedded devices often have constrained CPU, memory, and power, and many cannot be easily patched. They frequently run specialized rather than general-purpose operating systems. They usually have limited processing power. Vendor updates are often infrequent or nonexistent."},{"id":"S110","o":"3.1","d":3,"q":"A company replaces individual branch office firewalls and VPN concentrators with a cloud-delivered service that combines SD-WAN with secure web gateway, CASB, and zero trust network access. What is this architecture called?","a":["Screened subnet","Secure access service edge","Software-defined networking","Network access control"],"c":1,"e":"SASE combines networking such as SD-WAN with cloud-delivered security services into one model. SDN separates the control and data planes of networking but is not a security service bundle. A screened subnet is a DMZ. NAC controls device admission to a network."},{"id":"S111","o":"3.1","d":3,"q":"A hospital deploys IoT infusion pumps. Which risk is MOST associated with these devices?","a":["Requirement for administrator privileges on every user account","Weak default security and limited patching capability","Excessive encryption slowing patient care","Inability to connect to wireless networks"],"c":1,"e":"IoT devices often ship with weak defaults and receive limited updates, creating long-term exposure. Excessive encryption is not a typical problem. These devices commonly connect over Wi-Fi. Administrator privileges on user accounts are unrelated."},{"id":"S112","o":"3.1","d":3,"q":"A company needs to keep a research network completely separated from all other networks, with data transferred only by authorized removable media. Which architecture achieves this?","a":["Air gap","Software-defined perimeter","Screened subnet","VLAN segmentation"],"c":0,"e":"An air gap provides physical separation with no network connection to other systems. VLANs are logical separation on shared hardware. A software-defined perimeter controls access logically. A screened subnet connects to both external and internal networks."},{"id":"S113","o":"3.1","d":3,"q":"An organization keeps sensitive workloads in its on-premises data center while using a public cloud for less sensitive web applications. What is a key security consideration of this hybrid model?","a":["Consistent identity, policy, and monitoring across both environments","Exclusive reliance on the cloud provider for on-premises security","Elimination of all network connections between environments","Removal of the need for encryption in transit"],"c":0,"e":"Hybrid environments require consistent identity management, policies, and visibility across on-premises and cloud resources. They normally need connectivity between environments. The provider does not secure on-premises systems. Data moving between environments still needs encryption in transit."},{"id":"S114","o":"3.1","d":3,"q":"Which benefit does centralized architecture offer compared with decentralized architecture from a security perspective?","a":["Consistent policy enforcement","Reduced attractiveness to attackers","No single point of failure","Higher resilience to regional outages"],"c":0,"e":"Centralization makes it easier to apply consistent controls and monitor everything in one place. However, it introduces a single point of failure, reduces resilience compared to distributed designs, and makes the central system an attractive target."},{"id":"S115","o":"3.1","d":3,"q":"A company's real-time operating system controls robotic arms on an assembly line. Why is availability prioritized over confidentiality for this system?","a":["Encryption is mandatory for all real-time systems","The system processes large volumes of customer data","Delays or failures can halt production and create safety risks","Real-time systems cannot be logged"],"c":2,"e":"RTOS environments require deterministic timing, and disruption can stop production or endanger workers, so availability is critical. They usually do not handle large customer datasets. Encryption is not mandatory for all such systems. Logging is possible, though constrained."},{"id":"S116","o":"3.1","d":3,"q":"A cloud architect is concerned that a single misconfigured API key could expose all of the company's cloud resources. Which practice BEST reduces this risk?","a":["Embed API keys in source code for easier management","Scope API keys with least privilege and rotate them","Disable logging for API calls","Use a single shared key for all services"],"c":1,"e":"Limiting each key's permissions and rotating keys reduces the impact of exposure. Embedding keys in source code risks leaks through repositories. A shared key maximizes the blast radius. Disabling logging removes visibility into misuse."},{"id":"S117","o":"3.2","d":3,"q":"A company places its public web servers in a network zone that is reachable from the internet but separated from the internal LAN by a second firewall. What is this zone called?","a":["Air-gapped network","Intranet","Management VLAN","Screened subnet"],"c":3,"e":"A screened subnet, also called a DMZ, hosts public-facing services between external and internal firewalls. The intranet is the internal network. An air-gapped network has no external connections. A management VLAN is used for administrative traffic."},{"id":"S118","o":"3.2","d":3,"q":"A firewall rule set contains explicit allow rules for required traffic, and any traffic that does not match an allow rule is blocked by default. Which principle does this behavior implement?","a":["Port mirroring","Fail open","Implicit deny","Least functionality through allow listing applications"],"c":2,"e":"Denying everything not explicitly allowed is implicit deny, a fundamental firewall principle. Least functionality concerns system configuration rather than a final firewall rule. Fail open allows traffic when a device fails, which is the opposite. Port mirroring copies traffic for analysis."},{"id":"S119","o":"3.2","d":3,"q":"A network engineer must ensure that if the inline IPS fails, traffic to the online store continues to flow, because downtime is considered a greater business risk than temporary loss of inspection. Which configuration should be used?","a":["Fail closed","Out-of-band monitoring only","Fail open","Active-passive with no bypass"],"c":2,"e":"Fail open allows traffic to pass if the device fails, prioritizing availability as the business requires. Fail closed blocks traffic on failure, prioritizing security. Active-passive without bypass still interrupts traffic if both fail. Out-of-band monitoring would not provide inline prevention at all."},{"id":"S120","o":"3.2","d":3,"q":"Remote employees need secure access to internal applications from home. The company wants all traffic between the laptops and the corporate network encrypted. Which solution is MOST appropriate?","a":["Public RDP access with strong passwords","Unencrypted GRE tunnel","IPsec or TLS VPN","Port forwarding on the edge router"],"c":2,"e":"A VPN using IPsec or TLS creates an encrypted tunnel to the corporate network. Port forwarding exposes internal services directly. Public RDP is a common attack target even with strong passwords. GRE alone does not encrypt traffic."},{"id":"S121","o":"3.2","d":3,"q":"Which device inspects traffic at the application layer and can block specific web attacks such as SQL injection and cross-site scripting targeting a web application?","a":["Load balancer without security features","Layer 4 stateful firewall","Network switch with VLANs","Web application firewall"],"c":3,"e":"A WAF inspects HTTP traffic and blocks application-layer attacks against web apps. A Layer 4 firewall filters by IP and port and does not understand web payloads. VLANs segment networks but do not inspect application content. A basic load balancer distributes traffic without inspection."},{"id":"S122","o":"3.2","d":3,"q":"A company wants to prevent unauthorized devices from connecting to its wired network by authenticating each device before granting access to a switch port. Which technology should be used?","a":["802.1X with a RADIUS server","Spanning Tree Protocol","Static routing","Network address translation"],"c":0,"e":"802.1X provides port-based network access control, authenticating devices through RADIUS before allowing traffic. Static routing defines paths, not access. STP prevents switching loops. NAT translates addresses but does not authenticate devices."},{"id":"S123","o":"3.2","d":3,"q":"Administrators must connect to servers in a protected network segment. Security wants all administrative sessions to pass through a single hardened, monitored system. What should be deployed?","a":["Jump server","Honeypot","Load balancer","Proxy server for web browsing"],"c":0,"e":"A jump server is a hardened host administrators use to access protected systems, centralizing control and monitoring. A web proxy handles user web traffic. A honeypot is a decoy. A load balancer distributes client traffic."},{"id":"S124","o":"3.2","d":3,"q":"A company wants to inspect employee web traffic, block malicious sites, and enforce acceptable use policies. Which device is MOST suitable?","a":["Forward proxy with URL filtering","Layer 2 switch","Network tap","Reverse proxy in front of web servers"],"c":0,"e":"A forward proxy handles outbound requests from users and can filter URLs and inspect content. A reverse proxy protects internal servers from inbound requests. A switch forwards frames without content filtering. A tap copies traffic for monitoring but cannot block it."},{"id":"S125","o":"3.2","d":3,"q":"Which wireless security protocol uses Simultaneous Authentication of Equals to resist offline dictionary attacks against the passphrase?","a":["WPA2-PSK","WEP","WPA3","WPA with TKIP"],"c":2,"e":"WPA3 uses SAE, which protects against offline dictionary attacks even when the passphrase is weak. WPA2-PSK handshakes can be captured and attacked offline. WEP is broken. WPA with TKIP is deprecated and vulnerable."},{"id":"S126","o":"3.2","d":3,"q":"An organization wants to ensure that only its corporate laptops with current antivirus and patches can connect to the internal network, while noncompliant devices are placed in a remediation VLAN. Which solution provides this?","a":["Port mirroring","Static IP addressing","Network access control","DNS filtering"],"c":2,"e":"NAC checks device health and policy compliance before granting access and can quarantine noncompliant devices. Port mirroring copies traffic. DNS filtering blocks malicious domains. Static IP addressing does not evaluate device compliance."},{"id":"S127","o":"3.2","d":3,"q":"A company deploys sensors that passively monitor a copy of network traffic from a SPAN port. What is the limitation of this placement compared with an inline deployment?","a":["It cannot see encrypted traffic headers","It introduces latency into production traffic","It can detect but not directly block malicious traffic","It becomes a single point of failure for the network"],"c":2,"e":"Passive monitoring sees a copy of traffic, so it can alert but cannot stop packets in real time. Inline devices introduce latency and can be a point of failure, but passive ones do not. Passive sensors can still see packet headers even if payloads are encrypted."},{"id":"S128","o":"3.2","d":3,"q":"Which approach BEST protects a company's internal web applications from the internet while allowing remote employees access based on identity and device posture without exposing a full network tunnel?","a":["Traditional full-tunnel VPN","Public IP addresses on each application","Zero trust network access","Port knocking"],"c":2,"e":"ZTNA grants per-application access based on identity and context, without placing the user on the whole network. A full-tunnel VPN provides broad network access. Public IPs expose applications directly. Port knocking is obscurity rather than strong access control."},{"id":"S129","o":"3.2","d":3,"q":"A security architect is selecting a firewall that can identify applications regardless of the port used, integrate user identity, and perform intrusion prevention. Which type of firewall is required?","a":["Circuit-level gateway","Stateless ACL on a router","Next-generation firewall","Packet-filtering firewall"],"c":2,"e":"Next-generation firewalls add application awareness, user identity integration, and IPS capabilities. Packet-filtering firewalls and stateless ACLs only evaluate addresses and ports. Circuit-level gateways validate sessions but do not inspect application content."},{"id":"S130","o":"3.2","d":3,"q":"Switch ports in a conference room are configured to allow only one MAC address and to shut down if a different device is connected. Which feature is being used?","a":["DHCP reservation","Link aggregation","Quality of service","Port security"],"c":3,"e":"Port security restricts which MAC addresses can use a port and can disable it when violated. Link aggregation combines links for bandwidth. QoS prioritizes traffic. DHCP reservations assign specific IPs but do not block devices."},{"id":"S131","o":"3.2","d":3,"q":"Which practice MOST improves security when selecting infrastructure for a new data center network?","a":["Choosing devices that support secure management protocols and centralized logging","Choosing devices that only support Telnet for simplicity","Choosing the lowest-cost devices regardless of vendor support","Choosing devices without firmware update capability for stability"],"c":0,"e":"Support for secure protocols such as SSH and centralized logging enables secure administration and monitoring. Ignoring vendor support leads to unpatched devices. Telnet sends credentials in cleartext. Devices that cannot be updated cannot be fixed when vulnerabilities appear."},{"id":"S132","o":"3.2","d":3,"q":"A company deploys a reverse proxy in front of its customer-facing web servers. What is a PRIMARY security benefit?","a":["Masking the IP addresses of internal users browsing the web","Providing endpoint protection on the web servers","Filtering employee access to external websites","Hiding internal server details and centralizing TLS termination and filtering"],"c":3,"e":"A reverse proxy sits in front of backend servers, hides their details, can terminate TLS centrally, and filters inbound requests. Filtering employee web access and masking user IP addresses while browsing are forward proxy functions. Endpoint protection is provided by agents on the servers, not by a proxy."},{"id":"S133","o":"3.3","d":3,"q":"A company classifies its product roadmap documents so that only executives and product managers may read them, and disclosure would cause serious competitive harm. Which classification is MOST appropriate in a commercial setting?","a":["Public","Top secret","Confidential","Unclassified"],"c":2,"e":"Commercial organizations commonly use confidential for sensitive internal information whose disclosure causes significant harm. Public is for freely shareable information. Unclassified and top secret are government classifications."},{"id":"S134","o":"3.3","d":3,"q":"A help desk application displays only the last four digits of a customer's credit card number to support agents. Which data protection method is this?","a":["Geofencing","Hashing","Encryption at rest","Data masking"],"c":3,"e":"Data masking hides part of the data from users who do not need the full value. Encryption at rest protects stored data but would still reveal the full value to authorized viewers. Hashing is a one-way transformation for verification. Geofencing restricts access by location."},{"id":"S135","o":"3.3","d":3,"q":"European customer data must remain stored within EU borders due to regulatory requirements. Which concept does this describe?","a":["Data minimization","Data masking","Data obfuscation","Data sovereignty"],"c":3,"e":"Data sovereignty means data is subject to the laws of the country or region where it is stored, often requiring local storage. Data minimization limits collection to what is necessary. Masking and obfuscation hide data values but do not address location."},{"id":"S136","o":"3.3","d":3,"q":"A mobile banking app transmits account details between the phone and the bank's servers. Which state of data must be protected with TLS?","a":["Data at rest","Archived data","Data in transit","Data in use"],"c":2,"e":"Data moving across a network is data in transit, protected by protocols like TLS. Data at rest is stored on media. Data in use is being processed in memory. Archived data is long-term stored data, a form of data at rest."},{"id":"S137","o":"3.3","d":3,"q":"A company wants to prevent employees from emailing documents that contain national identification numbers to external addresses. Which solution BEST addresses this?","a":["Intrusion detection system","Web application firewall","Full disk encryption","Data loss prevention"],"c":3,"e":"DLP inspects content and enforces policies to block or alert on sensitive data leaving the organization. A WAF protects web applications. Full disk encryption protects stored data on lost devices. An IDS detects network attacks, not data handling policy violations."},{"id":"S138","o":"3.3","d":3,"q":"A research firm wants to analyze patient records without being able to identify individuals, while still preserving useful statistical properties. Which technique is MOST appropriate?","a":["Anonymization","Encryption with a shared key","Tokenization with a lookup vault","Digital signatures"],"c":0,"e":"Anonymization irreversibly removes identifying information while keeping data useful for analysis. Tokenization is reversible through the vault. Encrypted data can be decrypted by key holders. Signatures provide integrity, not privacy."},{"id":"S139","o":"3.3","d":3,"q":"Which method protects data while it is being processed in memory by an application?","a":["TLS 1.3","Full disk encryption","Secure enclaves","Database backups to tape"],"c":2,"e":"Secure enclaves isolate data in protected memory during processing, addressing data in use. TLS protects data in transit. Full disk encryption protects data at rest. Backups are a recovery measure."},{"id":"S140","o":"3.3","d":3,"q":"Which data type typically requires the strictest handling because its exposure can lead to identity theft?","a":["Personally identifiable information","Aggregated website traffic statistics","Product catalog pricing published online","Internal meeting schedules"],"c":0,"e":"PII such as names combined with identification numbers can be used for identity theft and is regulated in many jurisdictions. Aggregated traffic statistics do not identify people. Meeting schedules may be internal but rarely enable identity theft. Published pricing is public information."},{"id":"S141","o":"3.3","d":3,"q":"A company restricts access to a sensitive file share so that it can only be opened from devices located inside its offices in Zagreb and Vienna. Which method is being used?","a":["Permission inheritance","Geographic restrictions","Hashing","Data retention"],"c":1,"e":"Geographic restrictions control access based on location. Permission inheritance passes folder permissions to subfolders. Data retention defines how long data is kept. Hashing verifies integrity."},{"id":"S142","o":"3.3","d":3,"q":"An organization stores customer passwords and needs to verify them at login without being able to recover the original values. Which method should be used?","a":["Reversible encryption with AES","Tokenization","Salted hashing with a slow algorithm","Base64 encoding"],"c":2,"e":"Salted, slow hashing such as bcrypt or Argon2 allows verification without recovering the password. AES is reversible, so a key compromise reveals all passwords. Tokenization is designed for retrievable values. Base64 is encoding, trivially reversible, and not a security control."},{"id":"S143","o":"3.3","d":3,"q":"Which practice MOST directly reduces the impact of a breach by limiting what data is collected and stored in the first place?","a":["Data sovereignty","Data minimization","Data replication","Data obfuscation"],"c":1,"e":"Data minimization collects and retains only what is necessary, so less is exposed in a breach. Replication increases copies of data. Obfuscation hides data but it still exists. Sovereignty concerns location."},{"id":"S144","o":"3.3","d":3,"q":"A company protects the source code of its proprietary trading algorithm. Under which data type does this information primarily fall?","a":["Public information","Regulated payment card data","Personal health information","Intellectual property"],"c":3,"e":"Proprietary source code and algorithms are intellectual property and trade secrets. PHI relates to health data. Payment card data relates to cardholder information. Proprietary algorithms are not public."},{"id":"S145","o":"3.4","d":3,"q":"A company's business continuity plan states that the order processing system must be restored within 4 hours after an outage and may lose at most 15 minutes of data. Which metrics are these?","a":["4 hours is MTBF and 15 minutes is MTTR","4 hours is RPO and 15 minutes is RTO","Both values are the maximum tolerable downtime","4 hours is RTO and 15 minutes is RPO"],"c":3,"e":"Recovery time objective is the target time to restore a system, and recovery point objective is the maximum acceptable data loss measured in time. MTBF and MTTR are reliability metrics. Maximum tolerable downtime is the absolute limit before unacceptable harm and is not the data loss measure."},{"id":"S146","o":"3.4","d":3,"q":"A company maintains a secondary site with power, network connectivity, and racks, but no servers or data. Equipment would need to be delivered and configured after a disaster. Which site type is this?","a":["Mobile site already running production","Warm site","Hot site","Cold site"],"c":3,"e":"A cold site provides basic infrastructure without equipment or data, making it cheapest but slowest to activate. A hot site is fully equipped with current data. A warm site has some equipment and possibly older data. A mobile site running production would effectively be an active site."},{"id":"S147","o":"3.4","d":3,"q":"Which RAID level provides fault tolerance by striping data with distributed parity and can survive the failure of one disk?","a":["RAID 6","RAID 1","RAID 0","RAID 5"],"c":3,"e":"RAID 5 stripes data with distributed parity and tolerates one disk failure. RAID 0 has no redundancy. RAID 1 mirrors data rather than using parity. RAID 6 uses double parity and tolerates two failures."},{"id":"S148","o":"3.4","d":3,"q":"A web application runs on four servers behind a load balancer. If one server fails, the remaining servers continue handling requests. Which concept does this demonstrate?","a":["Tokenization","High availability","Data sovereignty","Cold site failover"],"c":1,"e":"Multiple servers behind a load balancer provide redundancy, so the service remains available if one fails. A cold site is a recovery location without equipment. Data sovereignty concerns location of data. Tokenization protects sensitive values."},{"id":"S149","o":"3.4","d":3,"q":"An administrator takes a full backup every Sunday and, on each weekday, backs up only the files changed since the last full backup. A server fails Thursday morning before that day's backup runs. Which backups are needed to restore the most recent data?","a":["Only Wednesday's backup","The Sunday full backup and every weekday backup through Wednesday","Only the Sunday full backup","The Sunday full backup and Wednesday's backup"],"c":3,"e":"Backing up all changes since the last full backup is a differential backup, so only the full backup and the most recent differential are needed. Needing every daily backup would apply to incremental backups. A differential alone or the full backup alone would not produce the latest state."},{"id":"S150","o":"3.4","d":3,"q":"A company tests its disaster recovery plan by actually switching production workloads to the secondary site for a weekend. Which type of test is this?","a":["Simulation without system changes","Checklist review","Tabletop exercise","Failover test"],"c":3,"e":"A failover test actually moves operations to the alternate site to verify it works. A tabletop exercise is a discussion. A simulation walks through a scenario without changing systems. A checklist review verifies plan contents."},{"id":"S151","o":"3.4","d":3,"q":"Why should backups be stored offsite or in a separate cloud region from the primary data center?","a":["Offsite backups are always faster to restore","Onsite storage violates every regulation","Offsite storage eliminates the need for encryption","A regional disaster could destroy both copies"],"c":3,"e":"Geographic separation protects backups from events that affect the primary site, such as fire or flood. Offsite backups still need encryption. They are often slower to restore. Onsite backups are allowed but insufficient alone."},{"id":"S152","o":"3.4","d":3,"q":"To protect backups from ransomware that targets backup repositories, which feature is MOST effective?","a":["Immutable backups that cannot be modified or deleted for a set period","Using the same administrator account for backups and production","Compressing backup files","Daily full backups stored on the same file server"],"c":0,"e":"Immutable backups cannot be altered or deleted during the retention window, even by attackers with credentials. Storing backups on the same server makes them reachable by ransomware. Compression does not protect integrity. Shared admin accounts increase exposure."},{"id":"S153","o":"3.4","d":3,"q":"A data center connects to two different internet service providers and has two power feeds from separate substations. What does this design PRIMARILY address?","a":["Data classification","Least privilege","Single points of failure","Change management"],"c":2,"e":"Using multiple ISPs and power sources removes single points of failure in critical services. Data classification labels information. Change management controls modifications. Least privilege limits permissions."},{"id":"S154","o":"3.4","d":3,"q":"An organization uses servers and network devices from two different vendors in its redundant infrastructure so that a single vendor vulnerability cannot take down both. What concept is this?","a":["Platform diversity","Journaling","Snapshots","Load balancing"],"c":0,"e":"Platform or vendor diversity reduces the chance that one flaw affects all redundant components. Load balancing distributes traffic. Snapshots capture system state at a point in time. Journaling records changes for recovery."},{"id":"S155","o":"3.4","d":3,"q":"A generator is installed at a hospital, but it takes 30 seconds to start after a power failure. Which additional component should be used to keep critical systems running during this gap?","a":["Power distribution unit without battery","Additional cooling unit","Surge protector","Uninterruptible power supply"],"c":3,"e":"A UPS provides immediate battery power until the generator starts. A PDU distributes power but does not store it. A surge protector limits voltage spikes. Cooling does not supply power."},{"id":"S156","o":"3.4","d":3,"q":"Which document defines how an organization continues critical business functions during and after a disruption, including people, processes, and communication, rather than focusing only on IT systems?","a":["Incident response plan","Acceptable use policy","Disaster recovery plan","Business continuity plan"],"c":3,"e":"The BCP covers continuation of essential business functions broadly. The DRP focuses on restoring IT systems. The IRP addresses handling security incidents. An AUP governs acceptable use of resources."},{"id":"S157","o":"4.1","d":4,"q":"A company issues smartphones to employees and needs to enforce screen locks, push approved apps, and remotely wipe lost devices. Which solution should be deployed?","a":["Data loss prevention on email","Mobile device management","Host-based intrusion detection","Network access control"],"c":1,"e":"MDM centrally enforces policies, distributes apps, and wipes lost devices. NAC controls network admission. Email DLP prevents data leakage through email. HIDS detects suspicious activity on a host but does not manage device configuration."},{"id":"S158","o":"4.1","d":4,"q":"A company allows employees to use personal phones for work. It wants to keep corporate data separate from personal apps and wipe only corporate data when an employee leaves. What should be implemented?","a":["Disabling Bluetooth","Jailbreak detection only","Containerization through MDM","Full device wipe policy"],"c":2,"e":"Containerization separates corporate apps and data into a managed container that can be wiped independently. A full wipe would delete personal data. Jailbreak detection alone does not separate data. Disabling Bluetooth does not address data separation."},{"id":"S159","o":"4.1","d":4,"q":"A security team establishes a documented, approved configuration for all Windows servers and uses a tool to detect any server that drifts from it. What is the documented configuration called?","a":["Risk register","Service level agreement","Incident playbook","Secure baseline"],"c":3,"e":"A secure baseline is the approved standard configuration against which systems are measured. A risk register tracks risks. An SLA defines service commitments. A playbook describes response steps for incidents."},{"id":"S160","o":"4.1","d":4,"q":"An administrator receives a new wireless controller and must configure it for an enterprise network where each user authenticates with their own directory credentials. Which mode should be used?","a":["WEP with MAC filtering","WPA3-Personal with a shared passphrase","WPA3-Enterprise with 802.1X","Open network with a captive portal"],"c":2,"e":"WPA3-Enterprise uses 802.1X and RADIUS for per-user authentication. WPA3-Personal uses a shared passphrase. Open networks provide no encryption by default. WEP is insecure and MAC filtering is easily bypassed."},{"id":"S161","o":"4.1","d":4,"q":"Developers want to ensure that user-supplied data in a web form is checked for expected type, length, and format before it is processed. What technique is this?","a":["Code signing","Static code analysis","Input validation","Sandboxing"],"c":2,"e":"Input validation checks data against expected rules before processing, reducing injection and logic flaws. Code signing verifies software origin. Static analysis reviews code without executing it. Sandboxing runs code in an isolated environment."},{"id":"S162","o":"4.1","d":4,"q":"Before releasing an application, a team scans its source code for vulnerabilities without running the program. Which testing method is being used?","a":["Static application security testing","Fuzzing","Penetration testing in production","Dynamic application security testing"],"c":0,"e":"SAST analyzes source code without executing it. DAST tests a running application. Fuzzing sends random or malformed input to a running program. Penetration testing simulates attacks against live systems."},{"id":"S163","o":"4.1","d":4,"q":"A security analyst wants to open a suspicious email attachment to observe its behavior without risking the corporate network. Which technique should be used?","a":["Tokenization","Sandboxing","Port mirroring","Load balancing"],"c":1,"e":"A sandbox is an isolated environment where code can run and be observed safely. Port mirroring copies network traffic. Load balancing distributes requests. Tokenization replaces sensitive data with tokens."},{"id":"S164","o":"4.1","d":4,"q":"Which hardening step is MOST appropriate for a new switch before it is connected to the production network?","a":["Allow all VLANs on every access port","Change default credentials and disable unused ports","Leave SNMP community strings at public and private","Enable Telnet for remote management"],"c":1,"e":"Changing defaults and disabling unused ports reduces unauthorized access. Telnet is insecure. Default SNMP strings are widely known. Allowing all VLANs on access ports enables VLAN hopping and unnecessary exposure."},{"id":"S165","o":"4.1","d":4,"q":"A company wants to make sure that its workstations boot only with signed, trusted bootloaders and operating system components. Which feature should be enabled?","a":["BIOS password only","Full disk compression","Secure Boot","Wake-on-LAN"],"c":2,"e":"Secure Boot verifies digital signatures of boot components to block rootkits and bootkits. A BIOS password restricts firmware settings but does not verify boot code. Compression is unrelated. Wake-on-LAN powers on devices remotely."},{"id":"S166","o":"4.1","d":4,"q":"An organization deploys a fleet of point-of-sale terminals. Which configuration BEST reduces risk on these single-purpose devices?","a":["Granting local administrator rights to cashiers","Allowing USB storage for convenience","Kiosk mode with an application allow list","Installing general productivity software"],"c":2,"e":"Locking devices into a single application with an allow list minimizes attack surface. Local admin rights allow users to install software. Extra software increases exposure. USB storage enables malware and data theft."},{"id":"S167","o":"4.2","d":4,"q":"A company discovers several servers in the data center that are not listed in its asset inventory and have not received patches. What is the MOST important first step to prevent this issue in the future?","a":["Purchase cyber insurance","Disable all logging on unknown servers","Increase the frequency of password changes","Maintain an accurate, regularly updated asset inventory"],"c":3,"e":"You cannot protect what you do not know exists; an accurate inventory ensures all assets are managed and patched. Disabling logging reduces visibility. Password changes do not address unmanaged assets. Insurance transfers financial risk but does not fix the gap."},{"id":"S168","o":"4.2","d":4,"q":"A company is retiring old laptops and will donate them to a school. Which method ensures data cannot be recovered while keeping the drives usable?","a":["Secure overwrite or cryptographic erase","Physical shredding","Quick formatting the drives","Deleting files and emptying the recycle bin"],"c":0,"e":"Overwriting or cryptographic erasure makes data unrecoverable while leaving drives functional. Deleting files and quick formatting leave data recoverable. Shredding destroys the drives, preventing reuse."},{"id":"S169","o":"4.2","d":4,"q":"After a hard drive containing sensitive data is destroyed by a third-party vendor, what should the company obtain as proof?","a":["Service level agreement","Purchase order","Certificate of destruction","Memorandum of understanding"],"c":2,"e":"A certificate of destruction documents that media was destroyed, supporting compliance and audits. An SLA defines service levels. A purchase order authorizes procurement. An MOU outlines a general agreement between parties."},{"id":"S170","o":"4.2","d":4,"q":"Which practice ensures that every asset has a person accountable for its security, maintenance, and appropriate use?","a":["Enabling auto-updates","Assigning asset ownership","Using a hot site","Applying data masking"],"c":1,"e":"Assigning an owner creates accountability for each asset. Auto-updates help patching but do not assign responsibility. Masking protects data values. A hot site supports recovery."},{"id":"S171","o":"4.2","d":4,"q":"A company must keep financial records for seven years due to legal requirements and then dispose of them securely. Which concept governs this?","a":["Data replication","Data obfuscation","Data sovereignty","Data retention"],"c":3,"e":"Data retention defines how long data must be kept and when it should be disposed of. Sovereignty concerns jurisdiction. Obfuscation hides data. Replication creates copies."},{"id":"S172","o":"4.2","d":4,"q":"During procurement of new network appliances, the security team requires vendors to provide a software bill of materials. What is the PRIMARY purpose?","a":["Confirm the licensing terms of the operating system","Verify the appliance's hardware warranty status","Replace the need for vulnerability scanning","Identify third-party components that may contain vulnerabilities"],"c":3,"e":"An SBOM lists the software components and libraries in a product so the organization can track and respond to vulnerabilities in them. Warranty and licensing are procurement concerns that an SBOM does not address. An SBOM complements vulnerability scanning but does not replace it."},{"id":"S173","o":"4.3","d":4,"q":"A vulnerability scanner reports that a Linux server is vulnerable to a Windows-specific flaw. After investigation, the team confirms the finding is not applicable. What is this called?","a":["Zero-day","True positive","False positive","False negative"],"c":2,"e":"A false positive reports a vulnerability that does not exist. A false negative misses a real vulnerability. A true positive is a correct finding. A zero-day is an unknown vulnerability with no fix available."},{"id":"S174","o":"4.3","d":4,"q":"Which scoring system is commonly used to rate the severity of vulnerabilities on a scale from 0 to 10?","a":["Common Vulnerabilities and Exposures","Security Content Automation Protocol","Common Vulnerability Scoring System","Annualized loss expectancy"],"c":2,"e":"CVSS provides a numeric severity score from 0 to 10. CVE assigns unique identifiers to vulnerabilities but does not score them. SCAP is a framework for automating security assessments. ALE is a risk calculation in monetary terms."},{"id":"S175","o":"4.3","d":4,"q":"A vulnerability scanner using only network access reports fewer findings than expected. The team then scans again with administrative credentials and discovers many missing patches. What explains the difference?","a":["Credentialed scans only check open ports","Credentialed scans disable host firewalls permanently","Credentialed scans can inspect installed software and configurations","Non-credentialed scans always detect more vulnerabilities"],"c":2,"e":"Credentialed scans log into hosts and examine installed packages, registry settings, and configurations, producing more accurate results. Checking open ports is what non-credentialed scans primarily do. Non-credentialed scans usually detect less. Credentialed scans do not permanently change firewall settings."},{"id":"S176","o":"4.3","d":4,"q":"A critical vulnerability is found on a production system, but the patch cannot be applied for three weeks due to vendor certification. What should the team do in the meantime?","a":["Implement compensating controls and document an exception","Shut down the business permanently","Ignore the vulnerability until the patch is available","Remove the vulnerability from the scan report"],"c":0,"e":"Compensating controls such as segmentation or WAF rules reduce risk until patching, and a documented exception records the accepted risk. Ignoring it leaves exposure unmanaged. Permanent shutdown is disproportionate. Removing findings from reports hides risk."},{"id":"S177","o":"4.3","d":4,"q":"After applying patches for findings from last month's scan, what is the NEXT step to confirm remediation was successful?","a":["Rescan the affected systems","Close all tickets without verification","Begin a penetration test of unrelated systems","Update the asset inventory only"],"c":0,"e":"Rescanning validates that the vulnerabilities are actually remediated. Closing tickets without checking may leave issues unresolved. Inventory updates are useful but do not confirm remediation. Testing unrelated systems does not verify these fixes."},{"id":"S178","o":"4.3","d":4,"q":"An organization pays independent researchers who report vulnerabilities in its public web applications. What is this program called?","a":["Tabletop exercise","Red team exercise","Threat feed subscription","Bug bounty program"],"c":3,"e":"A bug bounty rewards external researchers for reporting vulnerabilities. A red team exercise is an authorized simulated attack by a hired team. A threat feed provides intelligence on threats. A tabletop exercise discusses incident scenarios."},{"id":"S179","o":"4.3","d":4,"q":"Two vulnerabilities have the same CVSS score. One is on an internet-facing payment server, and the other is on an isolated lab machine. How should they be prioritized?","a":["Treat both identically because the scores match","Prioritize the payment server due to exposure and asset criticality","Prioritize neither until the scores change","Prioritize the lab machine because it is easier to patch"],"c":1,"e":"Prioritization should consider environmental factors such as exposure and business impact, not only base scores. Ease of patching does not outweigh risk. Identical scores do not mean identical risk in context. Waiting for score changes leaves risk unaddressed."},{"id":"S180","o":"4.3","d":4,"q":"A security team wants information about vulnerabilities being actively exploited and new attacker techniques, gathered from public sources such as government advisories and security blogs. What is this source called?","a":["Open-source intelligence","Dark web marketplace","Internal audit report","Proprietary threat feed"],"c":0,"e":"OSINT comes from publicly available sources. Proprietary feeds are paid commercial sources. Dark web marketplaces are not public in the usual sense and carry legal and safety concerns. Internal audits evaluate internal controls."},{"id":"S181","o":"4.3","d":4,"q":"A vulnerability scan identifies a flaw in a legacy reporting tool. Management decides not to fix it because the cost of remediation exceeds the potential loss, and formally signs off on this decision. What is this response called?","a":["Risk mitigation","Risk acceptance","Risk transference","Risk avoidance"],"c":1,"e":"Formally choosing to tolerate a risk after analysis is acceptance. Avoidance eliminates the activity causing risk. Transference shifts risk, for example through insurance. Mitigation applies controls to reduce risk."},{"id":"S182","o":"4.3","d":4,"q":"Which activity is part of the vulnerability management lifecycle and helps decide which issues to fix first?","a":["Purchasing new hardware for every finding","Deleting old scan reports","Disabling all external services permanently","Analysis and prioritization of findings"],"c":3,"e":"Analyzing and prioritizing findings by severity and context determines remediation order. Purchasing hardware is not a standard response. Deleting reports removes history. Permanently disabling services is disproportionate."},{"id":"S183","o":"4.4","d":4,"q":"A company wants a system that collects logs from firewalls, servers, and applications, correlates events, and generates alerts on suspicious patterns. Which tool should be deployed?","a":["DLP","WAF","SIEM","NAC"],"c":2,"e":"A SIEM aggregates and correlates logs from many sources to detect threats. DLP prevents sensitive data leakage. NAC controls network admission. A WAF protects web applications."},{"id":"S184","o":"4.4","d":4,"q":"Analysts complain that the SIEM generates hundreds of low-value alerts each day, causing important alerts to be missed. What should be done?","a":["Tune alert thresholds and correlation rules","Increase log retention to five years","Disable the SIEM","Forward all alerts to every employee"],"c":0,"e":"Tuning reduces noise so analysts can focus on meaningful alerts, addressing alert fatigue. Disabling the SIEM removes visibility. Longer retention does not reduce noise. Sending alerts to everyone worsens the problem."},{"id":"S185","o":"4.4","d":4,"q":"A network team uses a protocol that collects metadata about traffic flows, such as source, destination, ports, and byte counts, without capturing full packet payloads. Which protocol is this?","a":["Syslog","NetFlow","SNMP traps","LDAP"],"c":1,"e":"NetFlow records flow metadata for traffic analysis. SNMP traps send device status notifications. Syslog transports log messages. LDAP is a directory access protocol."},{"id":"S186","o":"4.4","d":4,"q":"A file integrity monitoring tool alerts that a system binary on a web server changed outside of a change window. What does this MOST likely indicate?","a":["Routine password expiration","A successful backup","Normal network congestion","Possible system compromise"],"c":3,"e":"Unexpected changes to system binaries can indicate tampering, such as a rootkit. Network congestion does not modify files. Backups copy files rather than changing them. Password expiration does not change binaries."},{"id":"S187","o":"4.4","d":4,"q":"Which practice ensures that logs from different systems can be accurately correlated during an investigation?","a":["Synchronizing all systems to a common time source","Compressing logs daily","Using different time zones per department","Storing logs only locally on each host"],"c":0,"e":"Consistent time synchronization, such as via NTP, allows events to be lined up across systems. Local-only storage risks loss and tampering. Compression does not affect correlation. Inconsistent time zones complicate correlation."},{"id":"S188","o":"4.4","d":4,"q":"A security analyst wants to detect when a sensitive file share is accessed outside business hours. Which approach is MOST effective?","a":["Increase the file share's storage quota","Audit access and alert on off-hours use","Install a new antivirus engine","Disable file share permissions"],"c":1,"e":"Auditing access and alerting on unusual times provides detection of suspicious activity. Storage quotas do not detect access. Disabling permissions breaks access control. Antivirus detects malware, not access patterns."},{"id":"S189","o":"4.4","d":4,"q":"Which activity verifies that alerts generated by the monitoring system are accurate and reach the right people?","a":["Load balancing","Alert validation","Asset decommissioning","Data minimization"],"c":1,"e":"Validating alerts and testing response ensures monitoring works as intended. Data minimization limits stored data. Decommissioning retires assets. Load balancing distributes traffic."},{"id":"S190","o":"4.4","d":4,"q":"A company wants to collect logs from all Linux servers in a central location for analysis and to protect them from local tampering. Which method should be used?","a":["Email logs to administrators daily","Forward logs using syslog to a central server","Keep logs only in each server's local directory","Delete logs weekly to save space"],"c":1,"e":"Centralized log forwarding protects logs from local tampering and enables analysis. Local-only logs can be deleted by an attacker. Deleting logs removes evidence. Emailing logs is impractical and insecure."},{"id":"S191","o":"4.4","d":4,"q":"Which tool continuously scans cloud environments for misconfigurations such as publicly exposed storage and overly permissive security groups?","a":["Hardware security module","Cloud security posture management","Proxy auto-configuration file","Packet sniffer"],"c":1,"e":"CSPM tools continuously assess cloud configurations against best practices. Packet sniffers capture network traffic. HSMs protect keys. PAC files configure proxy settings."},{"id":"S192","o":"4.4","d":4,"q":"An organization's SIEM shows an alert that turns out to be benign activity, while a real attack produced no alert at all. Which statement BEST describes these two outcomes?","a":["The first is a false negative and the second is a false positive","The first is a false positive and the second is a false negative","Both are true negatives","Both are true positives"],"c":1,"e":"A false positive is an alert for benign activity, and a false negative is a missed real attack. True positives are correct alerts for real attacks. True negatives are correctly not alerting on benign activity."},{"id":"S193","o":"4.5","d":4,"q":"A company wants to block employees from accessing newly registered and known malicious domains without deploying agents on every endpoint. Which control is MOST efficient?","a":["DNS filtering","Full disk encryption","Host-based firewall rules on each laptop","Port security"],"c":0,"e":"DNS filtering blocks malicious domains centrally by refusing to resolve them. Full disk encryption protects stored data. Host firewalls require per-device configuration. Port security restricts devices on switch ports."},{"id":"S194","o":"4.5","d":4,"q":"To reduce email spoofing of its domain, a company publishes a DNS record listing which mail servers are authorized to send email for the domain. Which record is this?","a":["SPF","DMARC","DKIM","MX"],"c":0,"e":"SPF lists authorized sending servers. DKIM adds a cryptographic signature to messages. DMARC defines a policy for handling SPF and DKIM failures and reporting. MX records direct incoming mail."},{"id":"S195","o":"4.5","d":4,"q":"A company has published SPF and DKIM records and now wants receiving servers to reject messages that fail these checks and to send reports. Which mechanism should be implemented?","a":["S/MIME","TLS","DNSSEC","DMARC"],"c":3,"e":"DMARC instructs receivers how to handle authentication failures and provides reporting. DNSSEC protects DNS integrity. S/MIME encrypts and signs individual emails. TLS encrypts mail in transit between servers."},{"id":"S196","o":"4.5","d":4,"q":"After a phishing campaign, the security team adds a firewall rule to block outbound traffic to the attacker's command and control IP addresses. Which type of capability modification is this?","a":["Enabling least privilege","Implementing data classification","Configuring RAID","Blocking known malicious indicators"],"c":3,"e":"Adding block rules for known malicious indicators modifies firewall capabilities. Data classification labels information. Least privilege restricts permissions. RAID provides storage redundancy."},{"id":"S197","o":"4.5","d":4,"q":"An IPS is detecting an exploit attempt but only generating alerts. The security team wants the device to stop the traffic automatically. What change is required?","a":["Configure the IPS signatures to block or drop","Increase the logging verbosity only","Disable signature updates","Move the IPS to a SPAN port"],"c":0,"e":"Setting rules to block or drop enables prevention. Moving to a SPAN port makes it passive and unable to block. Disabling updates reduces detection. More logging does not stop the attack."},{"id":"S198","o":"4.5","d":4,"q":"A company wants to inspect HTTPS traffic for malware but cannot see the encrypted content. What capability must be added to its secure web gateway?","a":["Disabling TLS on all websites","TLS inspection","MAC address filtering","Static NAT"],"c":1,"e":"TLS inspection decrypts and re-encrypts traffic using a certificate trusted by endpoints, allowing content inspection. Disabling TLS is not possible or appropriate. MAC filtering and static NAT do not provide visibility into encrypted content."},{"id":"S199","o":"4.5","d":4,"q":"Which group policy setting BEST mitigates the risk of malware spreading through USB drives on corporate workstations?","a":["Restrict removable storage","Allow users to install drivers","Increase screen saver timeout","Disable Windows Update"],"c":0,"e":"Restricting removable media prevents infection and data theft through USB devices. Screen saver timeouts affect session locking. Allowing driver installation increases risk. Disabling updates increases vulnerability."},{"id":"S200","o":"4.5","d":4,"q":"A web application is being attacked with requests containing SQL injection patterns. The developers need several days to fix the code. What is the BEST immediate action?","a":["Disable logging on the web server","Change the server's IP address","Increase the server's CPU","Add WAF rules for the attack patterns"],"c":3,"e":"WAF rules can virtually patch the application by filtering malicious requests until the code is fixed. Disabling logging reduces visibility. More CPU does not stop injection. Changing the IP only temporarily hinders attackers."},{"id":"S201","o":"4.5","d":4,"q":"A company wants to ensure that DNS responses received by its resolvers have not been tampered with in transit. Which technology should be enabled?","a":["DNSSEC","SNMPv1","SPF","DHCP snooping"],"c":0,"e":"DNSSEC signs DNS records so resolvers can validate their authenticity and integrity. SPF is for email sender authorization. DHCP snooping prevents rogue DHCP servers. SNMPv1 is an insecure management protocol."},{"id":"S202","o":"4.5","d":4,"q":"An attacker sets up a rogue DHCP server on the network, handing out a malicious default gateway. Which switch feature prevents this?","a":["Spanning Tree Protocol","Quality of service","DHCP snooping","Link aggregation"],"c":2,"e":"DHCP snooping allows DHCP responses only from trusted ports, blocking rogue servers. STP prevents loops. Link aggregation combines links. QoS prioritizes traffic."},{"id":"S203","o":"4.6","d":4,"q":"Employees log in once to the corporate portal and then access email, HR, and CRM applications without entering their credentials again. Which capability is provided?","a":["Account lockout","Single sign-on","Privileged access management","Multifactor authentication"],"c":1,"e":"SSO allows one authentication to grant access to multiple applications. MFA requires multiple factors but does not by itself remove repeated logins. PAM controls privileged accounts. Account lockout disables accounts after failed attempts."},{"id":"S204","o":"4.6","d":4,"q":"A company's web application lets users log in with their existing corporate identity provider. The identity provider sends a signed XML assertion to the application. Which standard is being used?","a":["SAML","OAuth 2.0 without OpenID Connect","Kerberos","LDAP"],"c":0,"e":"SAML uses XML assertions exchanged between an identity provider and a service provider for federated SSO. OAuth 2.0 alone is an authorization framework that uses tokens, not XML assertions. LDAP is a directory protocol. Kerberos uses tickets within a domain."},{"id":"S205","o":"4.6","d":4,"q":"A mobile app needs permission to read a user's calendar from a third-party service without receiving the user's password. Which framework is designed for this delegated authorization?","a":["TACACS+","SAML assertions only","OAuth","RADIUS"],"c":2,"e":"OAuth allows a user to grant an application limited access to resources through tokens without sharing passwords. SAML is primarily for authentication and SSO assertions. RADIUS and TACACS+ authenticate network access and device administration."},{"id":"S206","o":"4.6","d":4,"q":"A user authenticates with a password and then approves a push notification on a registered phone. Which authentication factors are being combined?","a":["Something you have and something you are","Something you are and somewhere you are","Something you know and something you are","Something you know and something you have"],"c":3,"e":"A password is something you know, and the registered phone is something you have. No biometric or location factor is used in this scenario."},{"id":"S207","o":"4.6","d":4,"q":"An access control model assigns permissions to job functions such as 'Accountant' or 'Help Desk', and users receive permissions by being placed in the appropriate function. Which model is this?","a":["Discretionary access control","Mandatory access control","Rule-based access control","Role-based access control"],"c":3,"e":"RBAC grants permissions based on roles. MAC uses labels and clearances set by the system. DAC lets resource owners decide access. Rule-based access control applies system-wide rules, such as time-of-day restrictions, regardless of role."},{"id":"S208","o":"4.6","d":4,"q":"A government system grants access only when a user's clearance level matches or exceeds the classification label of the document, and owners cannot change these permissions. Which access control model is used?","a":["Role-based access control","Attribute-based access control","Discretionary access control","Mandatory access control"],"c":3,"e":"MAC enforces access based on labels and clearances defined by a central authority, and owners cannot override them. DAC allows owners to grant access. RBAC uses roles. ABAC evaluates combinations of attributes rather than strict label hierarchies."},{"id":"S209","o":"4.6","d":4,"q":"Access to a payroll application is allowed only if the user is in the finance department, is using a managed device, and connects between 8 AM and 6 PM. Which access control model BEST describes this?","a":["Role-based access control only","Discretionary access control","Attribute-based access control","Mandatory access control"],"c":2,"e":"ABAC evaluates multiple attributes of the user, device, and environment to make decisions. DAC is owner-defined. MAC uses classification labels. Role-only RBAC would not consider device status and time together."},{"id":"S210","o":"4.6","d":4,"q":"An employee who moved from sales to marketing still has access to the sales CRM months later, along with new marketing permissions. What problem does this represent, and what process addresses it?","a":["Privilege creep, addressed by periodic access reviews","Impossible travel, addressed by geofencing","Shadow IT, addressed by firewall rules","Credential stuffing, addressed by password complexity"],"c":0,"e":"Accumulating permissions across role changes is privilege creep, and regular access reviews or recertification remove unneeded rights. Credential stuffing concerns reused passwords. Shadow IT involves unapproved services. Impossible travel concerns login locations."},{"id":"S211","o":"4.6","d":4,"q":"A company wants administrators to check out privileged credentials only when needed, with sessions recorded and passwords rotated after each use. Which solution should be deployed?","a":["Single sign-on portal","Privileged access management","Password complexity policy","Self-service password reset"],"c":1,"e":"PAM controls, monitors, and rotates privileged credentials, often with just-in-time access and session recording. SSO simplifies logins but does not manage privileged credentials. Complexity policies and self-service reset do not provide checkout or session recording."},{"id":"S212","o":"4.6","d":4,"q":"When an employee leaves the company, which action should occur FIRST in the deprovisioning process?","a":["Delete the employee's mailbox immediately","Reset the passwords of all other employees","Disable the user's accounts and revoke access","Archive the employee's performance reviews"],"c":2,"e":"Disabling accounts promptly prevents further access while preserving data needed for legal or business reasons. Immediate deletion may destroy records. Resetting everyone's passwords is unnecessary. Archiving reviews is an HR task unrelated to access control."},{"id":"S213","o":"4.6","d":4,"q":"Which authentication method is MOST resistant to phishing because the credential is bound to the legitimate website's origin?","a":["Security questions","SMS one-time code","FIDO2 security key","Email-based one-time link"],"c":2,"e":"FIDO2 keys use public key cryptography tied to the site's origin, so they will not authenticate to a fake site. SMS codes and email links can be relayed by phishing proxies or intercepted. Security questions are easily guessed or researched."},{"id":"S214","o":"4.6","d":4,"q":"Network administrators must authenticate to routers and switches, and the security team wants separate logging of authentication, authorization, and each command executed. Which protocol is BEST suited?","a":["RADIUS","TACACS+","LDAP","SAML"],"c":1,"e":"TACACS+ separates authentication, authorization, and accounting and supports per-command authorization and logging for device administration. RADIUS combines authentication and authorization and is commonly used for network access. LDAP is a directory protocol. SAML is for web SSO."},{"id":"S215","o":"4.7","d":4,"q":"A security team writes a script that automatically disables user accounts flagged by HR as terminated in the HR system. What is the PRIMARY benefit of this automation?","a":["Consistent and timely deprovisioning with fewer human errors","Faster internet connectivity for users","Elimination of the need for any access reviews","Removal of the need for audit logging"],"c":0,"e":"Automation ensures accounts are disabled promptly and consistently. Access reviews are still needed to catch other issues. Network speed is unaffected. Logging remains necessary for accountability."},{"id":"S216","o":"4.7","d":4,"q":"A SOC uses a platform that automatically enriches alerts with threat intelligence, opens tickets, and executes containment steps from predefined playbooks. Which technology is this?","a":["DLP","SOAR","CASB","SIEM without automation"],"c":1,"e":"SOAR orchestrates and automates security operations workflows using playbooks. A SIEM collects and correlates data but does not by itself execute response playbooks. DLP prevents data leakage. CASB secures cloud application usage."},{"id":"S217","o":"4.7","d":4,"q":"Which risk is MOST associated with heavy reliance on security automation?","a":["Automation prevents any form of logging","Automation requires removing all firewalls","Automation always increases analyst workload","A flawed script can propagate errors widely and quickly"],"c":3,"e":"Automated actions execute at scale, so a bug or bad logic can cause widespread disruption. Automation typically reduces workload. It does not prevent logging. It does not require removing firewalls."},{"id":"S218","o":"4.7","d":4,"q":"Developers configure their CI/CD pipeline to block any build that contains a known critical vulnerability in a dependency. Which concept does this demonstrate?","a":["Manual change advisory review","Risk transference","Guardrails enforced through automation","Physical security control"],"c":2,"e":"Automated checks that stop unsafe builds act as guardrails. Manual review is not automation. Risk transference shifts risk to a third party. The control is technical, not physical."},{"id":"S219","o":"4.7","d":4,"q":"A company automatically provisions new cloud servers from a hardened template and applies security agents at creation. Which benefit does this provide?","a":["Standardized secure configurations across all new servers","Elimination of patching requirements","Automatic compliance with all regulations","Removal of the need for vulnerability scanning"],"c":0,"e":"Automated provisioning from hardened templates ensures consistent, secure configurations and reduces misconfiguration. Servers still require patching and vulnerability scanning after deployment. Automation supports compliance but does not by itself make an organization compliant with every regulation."},{"id":"S220","o":"4.7","d":4,"q":"Which consideration is MOST important before automating the response of blocking IP addresses in the firewall?","a":["Preventing false positives from blocking legitimate business traffic","Ensuring the script runs with domain administrator rights","Suppressing alert notifications to reduce noise","Removing all manual override capabilities"],"c":0,"e":"Automated blocking based on incorrect detections can disrupt business, so validation and false positive safeguards are essential. Domain administrator rights violate least privilege and are not needed to update firewall rules. Manual overrides should remain so analysts can reverse bad decisions. Notifications are needed for oversight of automated actions."},{"id":"S221","o":"4.8","d":4,"q":"An analyst confirms that ransomware is spreading from a file server. According to the incident response process, what should happen NEXT after identification?","a":["Lessons learned","Preparation","Recovery","Containment"],"c":3,"e":"After identifying an incident, the next phase is containment to stop it from spreading. Eradication and recovery follow containment. Lessons learned occurs after recovery. Preparation happens before incidents."},{"id":"S222","o":"4.8","d":4,"q":"After an incident is resolved, the team meets to review what happened, what worked, and how procedures can be improved. Which phase is this?","a":["Eradication","Detection","Lessons learned","Containment"],"c":2,"e":"The lessons learned phase reviews the incident to improve future response. Containment limits spread. Eradication removes the cause. Detection identifies the incident."},{"id":"S223","o":"4.8","d":4,"q":"A team removes malware from infected systems, deletes attacker-created accounts, and closes the vulnerability that was exploited. Which phase does this describe?","a":["Eradication","Containment","Lessons learned","Preparation"],"c":0,"e":"Eradication removes the root cause and all artifacts of the incident. Containment limits damage but does not remove the threat. Preparation occurs before incidents. Lessons learned reviews the incident afterward."},{"id":"S224","o":"4.8","d":4,"q":"Which activity belongs to the preparation phase of incident response?","a":["Restoring systems from backups","Interviewing staff after an incident","Developing playbooks and training staff","Isolating infected hosts"],"c":2,"e":"Preparation includes creating plans, playbooks, tools, and training before incidents occur. Isolation is containment. Restoring is recovery. Post-incident interviews are part of lessons learned."},{"id":"S225","o":"4.8","d":4,"q":"Legal counsel informs the security team that a lawsuit related to a breach is expected. What must the team implement to ensure relevant data is preserved?","a":["Data minimization","Data masking","Retention policy deletion","Legal hold"],"c":3,"e":"A legal hold suspends normal deletion so relevant data is preserved for litigation. Data minimization and scheduled deletion would destroy needed evidence. Masking alters how data is displayed but does not preserve it."},{"id":"S226","o":"4.8","d":4,"q":"A forensic investigator documents every person who handled a seized laptop, along with dates and reasons, from collection to court presentation. What is this documentation called?","a":["Chain of custody","Order of volatility","Risk register","Service level agreement"],"c":0,"e":"Chain of custody records the handling of evidence to prove it was not tampered with. Order of volatility defines the sequence for collecting evidence. An SLA defines service commitments. A risk register tracks risks."},{"id":"S227","o":"4.8","d":4,"q":"When collecting evidence from a running system, which data should be captured FIRST according to the order of volatility?","a":["Printed documentation","Data on the hard disk","Contents of RAM and CPU cache","Archived backup tapes"],"c":2,"e":"Memory and cache are the most volatile and are lost when the system powers off. Disk data persists longer. Backups and printed documents are least volatile."},{"id":"S228","o":"4.8","d":4,"q":"A team gathers in a conference room to talk through how they would respond to a hypothetical ransomware attack, without touching any systems. What type of exercise is this?","a":["Penetration test","Failover test","Full-scale simulation","Tabletop exercise"],"c":3,"e":"A tabletop exercise is a discussion-based walkthrough of a scenario. A full simulation involves acting out the scenario with systems and teams. A penetration test attacks real systems. A failover test switches to backup systems."},{"id":"S229","o":"4.8","d":4,"q":"During an investigation, an analyst identifies that the attacker gained access through an unpatched VPN appliance. What is this finding called?","a":["Root cause","Mean time to repair","Indicator of attack only","Recovery point objective"],"c":0,"e":"The root cause is the underlying reason an incident occurred, here the unpatched appliance. An indicator of attack points to malicious activity but not the underlying cause. RPO and MTTR are recovery metrics."},{"id":"S230","o":"4.8","d":4,"q":"Before making a forensic image of a hard drive, an investigator connects it through a device that prevents any data from being written to the drive. Why?","a":["To preserve evidence integrity","To speed up data transfer","To remove malware from the drive","To encrypt the evidence"],"c":0,"e":"A write blocker prevents modification of the original evidence, preserving its integrity for analysis and legal use. It does not speed transfers, encrypt data, or remove malware."},{"id":"S231","o":"4.9","d":4,"q":"An analyst investigating a phishing incident wants to know which employees received the malicious message and whether any clicked the link. Which data sources are MOST useful?","a":["Badge reader logs and HVAC sensor data","Email gateway logs and web proxy logs","Firewall rule documentation only","Printer usage reports"],"c":1,"e":"Email gateway logs show recipients, and proxy logs show who visited the malicious URL. Badge and HVAC data relate to physical access and environment. Rule documentation shows configuration, not activity. Printer reports are unrelated."},{"id":"S232","o":"4.9","d":4,"q":"An investigator needs to determine which processes were running and which network connections existed on a compromised server at the time of the incident. Which source is MOST valuable?","a":["Memory dump","Firewall configuration backup","Network diagram","Vulnerability scan from last quarter"],"c":0,"e":"A memory dump captures running processes, connections, and in-memory artifacts. Configuration backups and diagrams describe intended setup. An old scan shows vulnerabilities at a past date."},{"id":"S233","o":"4.9","d":4,"q":"Which log source would BEST reveal that an attacker used PowerShell to download a tool on a Windows endpoint?","a":["Endpoint process creation logs","UPS battery logs","DHCP lease logs","Switch interface counters"],"c":0,"e":"Endpoint logs with process creation and command-line auditing record executed commands like PowerShell downloads. Switch counters show traffic volumes. DHCP logs map IPs to devices. UPS logs relate to power."},{"id":"S234","o":"4.9","d":4,"q":"An analyst needs to identify which internal host had IP address 10.1.4.27 three days ago when suspicious traffic occurred. Which data source should be checked?","a":["Group policy objects","Certificate revocation list","Antivirus definitions","DHCP logs"],"c":3,"e":"DHCP logs show which device was assigned a given IP address at a specific time. Antivirus definitions list signatures. A CRL lists revoked certificates. GPOs define configuration policies."},{"id":"S235","o":"4.9","d":4,"q":"A firewall log shows repeated connections from an internal host to TCP port 4444 on an external IP. What should the analyst do with this information FIRST?","a":["Ignore it because port 4444 is a standard web port","Change the firewall vendor","Correlate it with other data sources","Delete the firewall logs to save space"],"c":2,"e":"Correlating with other sources helps confirm whether this is a reverse shell or legitimate traffic before acting. Port 4444 is not a standard web port and is commonly associated with attack tools. Deleting logs destroys evidence. Changing vendors does not address the event."},{"id":"S236","o":"4.9","d":4,"q":"Which data source provides a high-level overview of security metrics and trends that can help managers understand incident patterns?","a":["Individual syslog entries","Raw packet captures","Dashboards and automated reports","Memory dumps"],"c":2,"e":"Dashboards and reports summarize data for decision makers. Packet captures, individual log entries, and memory dumps are detailed technical sources used by analysts."},{"id":"S237","o":"4.9","d":4,"q":"An investigator wants to see the exact content of data exchanged between a compromised host and an external server during an attack. Which source provides this level of detail?","a":["NetFlow records","DNS query logs","Authentication logs","Packet capture"],"c":3,"e":"Full packet captures include payloads, showing exactly what was transmitted. NetFlow shows metadata only. DNS logs show name lookups. Authentication logs show logins."},{"id":"S238","o":"4.9","d":4,"q":"An analyst suspects that an attacker accessed a database and exported records. Which log source would MOST directly confirm which queries were executed?","a":["Web proxy logs","Badge access logs","Database audit logs","Wireless controller logs"],"c":2,"e":"Database audit logs record queries and access to data. Proxy logs track web browsing. Badge logs track physical entry. Wireless logs track device associations."},{"id":"S239","o":"4.9","d":4,"q":"Vulnerability scan results are used during an incident investigation. How do they BEST support the investigation?","a":["They contain full packet payloads","They reveal weaknesses that may explain initial access","They record physical access to the data center","They show the attacker's real-time keystrokes"],"c":1,"e":"Scan results reveal existing vulnerabilities that may have been the entry point. They do not record keystrokes, packet payloads, or physical access."},{"id":"S240","o":"4.9","d":4,"q":"An investigator reviews metadata from a suspicious document sent to the finance team and finds the author name, creation date, and editing software. What type of data source is this?","a":["SNMP traps","NetFlow","File metadata","Load balancer health checks"],"c":2,"e":"File metadata contains attributes such as author, timestamps, and application used to create the file. NetFlow records traffic flows. SNMP traps report device events. Health checks verify service availability."},{"id":"S241","o":"5.1","d":5,"q":"A company's board approves a high-level document stating that information security is a business priority and assigning overall responsibility to the CISO. Which type of document is this?","a":["Information security policy","Technical baseline","Playbook","Standard operating procedure"],"c":0,"e":"A policy is a high-level statement of management intent and responsibilities. Procedures give step-by-step instructions. Baselines define minimum technical configurations. Playbooks define response actions for specific scenarios."},{"id":"S242","o":"5.1","d":5,"q":"Which document specifies mandatory requirements, such as 'all laptops must use AES-256 full disk encryption', that support a broader policy?","a":["Standard","Policy statement of intent","Guideline","Memorandum of understanding"],"c":0,"e":"Standards are mandatory, specific requirements that implement policies. Guidelines are recommended but optional. A policy states intent at a high level. An MOU is an agreement between parties."},{"id":"S243","o":"5.1","d":5,"q":"A department head is responsible for deciding how customer data is classified and who may access it, while IT manages the servers storing it. What role does the department head hold?","a":["Data owner","Data custodian","Data subject","Data processor"],"c":0,"e":"The data owner is accountable for classification and access decisions. The custodian, here IT, implements and maintains technical controls. A processor handles data on behalf of a controller. The data subject is the individual the data describes."},{"id":"S244","o":"5.1","d":5,"q":"Under privacy regulations, a cloud payroll provider processes employee data on behalf of a company that determines the purposes of the processing. What is the provider's role?","a":["Data controller","Data processor","Data owner","Data subject"],"c":1,"e":"A processor processes personal data on behalf of the controller. The controller decides why and how data is processed. Data owner is an internal governance role. The data subject is the person whose data is processed."},{"id":"S245","o":"5.1","d":5,"q":"Which governance structure places security decision-making with a central team that sets policies for all business units?","a":["Centralized governance","Shadow IT","Decentralized governance","Federated data processing"],"c":0,"e":"Centralized governance concentrates authority in one team for consistency. Decentralized governance distributes decisions to business units. Federated data processing is not a governance model. Shadow IT is unapproved technology use."},{"id":"S246","o":"5.1","d":5,"q":"A company creates a committee with representatives from IT, legal, HR, and business units to oversee security strategy and resolve conflicts between departments. What is this committee's PRIMARY purpose?","a":["Handle routine help desk tickets","Perform daily patching of servers","Replace the incident response team","Cross-functional oversight"],"c":3,"e":"A governance committee aligns security with business objectives across departments. Patching, incident response, and help desk work are operational tasks performed by other teams."},{"id":"S247","o":"5.1","d":5,"q":"Which policy defines what employees are allowed and not allowed to do with company IT resources, such as email and internet access?","a":["Business continuity policy","Change management policy","Data retention policy","Acceptable use policy"],"c":3,"e":"An AUP sets rules for appropriate use of IT resources. Business continuity policy covers maintaining operations. Change management policy governs system changes. Data retention policy defines how long data is kept."},{"id":"S248","o":"5.1","d":5,"q":"An organization documents a detailed sequence of steps that administrators must follow to onboard a new employee's accounts. What type of document is this?","a":["Guideline","Policy","Charter","Procedure"],"c":3,"e":"Procedures provide step-by-step instructions for specific tasks. Policies state high-level rules. Guidelines offer recommendations. A charter establishes the authority and purpose of a group."},{"id":"S249","o":"5.1","d":5,"q":"Which external consideration MOST influences the security governance of a hospital operating in multiple countries?","a":["Regulatory requirements in each jurisdiction","The preferences of the IT help desk staff","The number of data center racks in use","The organization's internal ticketing system"],"c":0,"e":"Laws and regulations in each jurisdiction, such as health data protection rules, are external considerations that shape governance requirements. The ticketing system, staff preferences, and rack counts are internal operational details that do not drive governance."},{"id":"S250","o":"5.1","d":5,"q":"Which role is responsible for performing backups, applying access controls, and maintaining storage systems according to the owner's requirements?","a":["Data controller","Data subject","Data custodian","Data owner"],"c":2,"e":"The custodian handles the technical day-to-day protection of data as directed by the owner. The owner defines requirements. The controller determines purposes of processing under privacy law. The subject is the individual the data concerns."},{"id":"S251","o":"5.1","d":5,"q":"A company wants to measure how effectively its security program is performing over time. What should it define and track?","a":["The total security budget spent each year","Key performance and risk indicators","The number of firewall rules configured","The number of security tools purchased"],"c":1,"e":"KPIs and KRIs measure outcomes and risk trends, showing whether the program is effective. Rule counts, spending, and the number of tools describe inputs and activity, not effectiveness; a large budget or many tools does not prove reduced risk."},{"id":"S252","o":"5.1","d":5,"q":"Which guidance is optional and offers recommended practices that employees may adapt to their situations?","a":["Guidelines","Regulations","Standards","Policies"],"c":0,"e":"Guidelines are advisory and flexible. Standards and policies are mandatory within the organization. Regulations are legally binding external requirements."},{"id":"S253","o":"5.2","d":5,"q":"A server worth 20,000 EUR has a 25 percent chance of being destroyed by flooding in a given year, and a flood would cause total loss. What is the annualized loss expectancy?","a":["80,000 EUR","20,000 EUR","25,000 EUR","5,000 EUR"],"c":3,"e":"SLE is the asset value times exposure factor, 20,000 x 1.0 = 20,000. ALE is SLE times ARO, 20,000 x 0.25 = 5,000. 20,000 is the SLE, not the ALE. The other values do not follow from the formula."},{"id":"S254","o":"5.2","d":5,"q":"A company buys cyber insurance to cover potential losses from a ransomware attack. Which risk response strategy is this?","a":["Transfer","Avoid","Accept","Mitigate"],"c":0,"e":"Insurance shifts the financial impact of a risk to a third party, which is transference. Avoidance stops the risky activity. Acceptance tolerates the risk. Mitigation reduces likelihood or impact through controls."},{"id":"S255","o":"5.2","d":5,"q":"A company decides not to launch a new online service in a country because the regulatory risk is too high. Which risk response is this?","a":["Acceptance","Mitigation","Transference","Avoidance"],"c":3,"e":"Avoidance eliminates the risk by not performing the activity. Transference shifts it to another party. Acceptance tolerates it. Mitigation reduces it while continuing the activity."},{"id":"S256","o":"5.2","d":5,"q":"A risk assessment uses ratings such as low, medium, and high based on expert judgment rather than monetary values. What type of assessment is this?","a":["Financial audit","Qualitative","Continuous automated","Quantitative"],"c":1,"e":"Qualitative assessments use descriptive scales and judgment. Quantitative assessments use numeric and monetary values such as ALE. Continuous automated describes frequency and method, not the scale. A financial audit reviews accounts."},{"id":"S257","o":"5.2","d":5,"q":"Which document lists identified risks along with their likelihood, impact, owners, and planned responses?","a":["Risk register","Service level agreement","Business impact analysis","Statement of work"],"c":0,"e":"A risk register records and tracks risks and how they are being addressed. A BIA assesses the impact of disruption on business processes. An SLA defines service levels. An SOW describes work to be performed."},{"id":"S258","o":"5.2","d":5,"q":"What does risk appetite describe?","a":["The level of risk the organization will pursue","The number of vulnerabilities found in a scan","The exact monetary value of every asset","The time required to restore systems"],"c":0,"e":"Risk appetite is the level of risk an organization is willing to take on to achieve its goals. Asset values feed into quantitative analysis. Vulnerability counts are scan results. Restoration time is RTO."},{"id":"S259","o":"5.2","d":5,"q":"After applying controls to reduce a risk, some level of risk still remains. What is this remaining risk called?","a":["Residual risk","Risk appetite","Inherent risk","Risk transference"],"c":0,"e":"Residual risk is what remains after controls are applied. Inherent risk is the level before controls. Risk appetite is the amount of risk the organization is willing to pursue. Transference is a response strategy."},{"id":"S260","o":"5.2","d":5,"q":"Which metric represents the expected number of times a specific threat event will occur in a year?","a":["Mean time to recovery","Exposure factor","Single loss expectancy","Annualized rate of occurrence"],"c":3,"e":"ARO is the expected frequency of an event per year. SLE is the loss from a single event. Exposure factor is the percentage of asset value lost. MTTR is the average time to restore service."},{"id":"S261","o":"5.2","d":5,"q":"A business impact analysis identifies that the online ordering system can be down for a maximum of 8 hours before the company suffers severe, possibly irreversible harm. What does this value represent?","a":["Recovery point objective","Mean time between failures","Maximum tolerable downtime","Annualized loss expectancy"],"c":2,"e":"MTD is the longest a process can be unavailable before unacceptable consequences. RPO is the acceptable data loss. MTBF measures reliability. ALE measures expected annual financial loss."},{"id":"S262","o":"5.2","d":5,"q":"A company has a policy that any risk with a residual rating above 'medium' must be escalated to executive management for a decision. What does this threshold represent?","a":["Exposure factor","Risk tolerance","Risk register entry","Inherent risk"],"c":1,"e":"Risk tolerance defines acceptable variation and thresholds at which risk must be addressed or escalated. Inherent risk is risk before controls. Exposure factor is part of quantitative loss calculation. A register entry records a risk but does not set the threshold."},{"id":"S263","o":"5.2","d":5,"q":"Which activity is the FIRST step in the risk management process?","a":["Risk identification","Risk response selection","Risk reporting","Risk monitoring"],"c":0,"e":"Risks must be identified before they can be analyzed, treated, monitored, or reported. The other activities depend on having identified risks first."},{"id":"S264","o":"5.2","d":5,"q":"A company's laptop has an asset value of 1,500 EUR. If stolen, the company loses the full value. Laptops are stolen about four times a year. What is the ALE for laptop theft?","a":["6,000 EUR","1,500 EUR","4 EUR","375 EUR"],"c":0,"e":"SLE equals 1,500 x 1.0 = 1,500 EUR, and ALE equals SLE x ARO = 1,500 x 4 = 6,000 EUR. 1,500 is the SLE. 375 would result from dividing rather than multiplying. 4 is the ARO."},{"id":"S265","o":"5.2","d":5,"q":"Management installs additional firewalls and intrusion prevention to lower the likelihood of a network breach. Which risk response is this?","a":["Transference","Acceptance","Avoidance","Mitigation"],"c":3,"e":"Adding controls to reduce likelihood or impact is mitigation. Avoidance stops the activity. Acceptance tolerates the risk unchanged. Transference shifts it to a third party."},{"id":"S266","o":"5.2","d":5,"q":"Which statement BEST describes a key risk indicator?","a":["A list of all employees with administrator rights","A one-time penetration test report","A contract clause transferring liability","A metric that provides early warning of increasing risk exposure"],"c":3,"e":"KRIs are metrics that signal changes in risk levels, enabling proactive responses. A list of admins is inventory data. Liability clauses transfer risk. A single test report is a point-in-time assessment."},{"id":"S267","o":"5.3","d":5,"q":"Before signing a contract with a new cloud backup provider, a company reviews the provider's security certifications, financial stability, and incident history. What is this activity called?","a":["Rules of engagement","Due care after contract termination","Due diligence","Right-to-audit enforcement"],"c":2,"e":"Due diligence is the investigation performed before entering a relationship to assess risk. Due care refers to ongoing responsible actions. Rules of engagement define testing boundaries. Right to audit is a contract clause exercised after signing."},{"id":"S268","o":"5.3","d":5,"q":"A contract with a vendor includes a clause allowing the customer to inspect the vendor's security controls and records. What is this clause called?","a":["Non-disclosure clause","Right-to-audit clause","Non-compete clause","Force majeure clause"],"c":1,"e":"A right-to-audit clause permits the customer to verify the vendor's controls. An NDA protects confidential information. Force majeure addresses events beyond control. Non-compete restricts competition."},{"id":"S269","o":"5.3","d":5,"q":"Which agreement defines measurable performance targets such as 99.9 percent uptime and response times for support requests?","a":["Memorandum of understanding","Service level agreement","Business partners agreement","Non-disclosure agreement"],"c":1,"e":"An SLA specifies measurable service levels and often penalties. An MOU is a less formal statement of intent. A BPA defines a business partnership. An NDA protects confidential information."},{"id":"S270","o":"5.3","d":5,"q":"Two organizations want to document their intent to cooperate on a joint security research project without creating strict legally binding obligations. Which document is MOST appropriate?","a":["Memorandum of understanding","Statement of work","Service level agreement","Master service agreement"],"c":0,"e":"An MOU outlines shared intentions and is often not strictly binding. An MSA sets binding terms for future work. An SLA defines measurable service levels. An SOW defines specific deliverables under a contract."},{"id":"S271","o":"5.3","d":5,"q":"A company has a master service agreement with a consulting firm. For each new project, a document is created describing deliverables, timelines, and costs. What is this document?","a":["Statement of work","Memorandum of agreement","Rules of engagement","Non-disclosure agreement"],"c":0,"e":"An SOW details specific deliverables and terms for an engagement under the MSA. An NDA protects confidentiality. An MOA defines cooperation terms. Rules of engagement define boundaries for security testing."},{"id":"S272","o":"5.3","d":5,"q":"An organization requires its suppliers to complete a security questionnaire annually and to notify it within 24 hours of any breach. What process does this support?","a":["Risk avoidance","Ongoing vendor monitoring","Data minimization","Penetration testing"],"c":1,"e":"Regular questionnaires and breach notification requirements support continuous monitoring of vendor risk. Avoidance eliminates a risky activity. Penetration testing simulates attacks. Data minimization limits data collected."},{"id":"S273","o":"5.3","d":5,"q":"A company is hiring a firm to perform a penetration test. Which document defines the scope, permitted techniques, testing times, and contacts?","a":["Rules of engagement","Acceptable use policy","Service level agreement","Business partners agreement"],"c":0,"e":"Rules of engagement define what testers may do, when, and how to communicate. An SLA defines service levels. A BPA defines a business partnership. An AUP governs employee resource use."},{"id":"S274","o":"5.3","d":5,"q":"A software vendor's update server is compromised, and malicious updates are pushed to customers. Which risk does this illustrate for the customers?","a":["Supply chain risk","Risk of excessive data minimization","Physical security failure","Insider threat from own employees"],"c":0,"e":"Compromise of a supplier affecting customers is supply chain risk. It did not originate from the customers' own employees. It is not physical. Data minimization does not cause this issue."},{"id":"S275","o":"5.3","d":5,"q":"Which factor is MOST important when selecting a vendor that will store regulated customer data?","a":["The vendor's ability to meet the company's security and compliance requirements","The vendor's office location relative to headquarters","The lowest price offered in the proposal","The number of customers listed on the vendor's website"],"c":0,"e":"Vendors handling regulated data must meet security and compliance obligations. Price matters but cannot outweigh the ability to protect regulated data. Office proximity does not indicate security capability. A long customer list is marketing, not evidence of adequate controls."},{"id":"S276","o":"5.3","d":5,"q":"An independent assessment report attests that a SaaS provider's controls over security and availability operated effectively over a twelve-month period. Which report is this?","a":["Vulnerability scan summary","Software bill of materials","SOC 2 Type II","SOC 1 Type I"],"c":2,"e":"A SOC 2 Type II report evaluates the operating effectiveness of controls related to trust services criteria over a period. SOC 1 focuses on financial reporting controls, and Type I is a point-in-time design review. A scan summary lists vulnerabilities. An SBOM lists software components."},{"id":"S277","o":"5.4","d":5,"q":"A company discovers it has been storing cardholder data in violation of PCI DSS requirements. Which consequence is MOST likely if this continues?","a":["Automatic suspension of the company's domain name","Mandatory replacement of all point-of-sale hardware","Fines and loss of card processing ability","A required migration to a different cloud provider"],"c":2,"e":"Noncompliance with PCI DSS can result in fines from card brands and acquirers and revocation of the ability to process card payments. Changing cloud providers, replacing all POS hardware, or losing the domain are not standard consequences of PCI DSS violations."},{"id":"S278","o":"5.4","d":5,"q":"Which activity helps an organization demonstrate ongoing compliance by regularly reporting control status to regulators or management?","a":["Compliance reporting and monitoring","Ignoring vendor assessments","Removing security policies","Disabling audit logs"],"c":0,"e":"Regular monitoring and reporting provide evidence of continued compliance. Disabling logs, removing policies, and ignoring vendor assessments would undermine compliance."},{"id":"S279","o":"5.4","d":5,"q":"A company must notify affected individuals and authorities within a specific time frame after a personal data breach. Which aspect of compliance does this represent?","a":["Physical security requirements","Breach notification requirements","Data retention requirements","Change management requirements"],"c":1,"e":"Laws such as GDPR require timely notification of breaches. Data retention concerns how long data is kept. Change management controls modifications. Physical security protects facilities."},{"id":"S280","o":"5.4","d":5,"q":"An employee reports a suspected compliance violation internally. Which practice supports this by protecting the employee from retaliation?","a":["Remote access policy","Whistleblower protection policy","Password expiration policy","Data masking policy"],"c":1,"e":"Whistleblower protections encourage reporting of violations without fear of retaliation. The other policies address unrelated technical controls."},{"id":"S281","o":"5.4","d":5,"q":"A company performs a self-assessment and signs a statement to its regulator confirming that it meets required controls. What is this called?","a":["Penetration test","Attestation","Root cause analysis","Business impact analysis"],"c":1,"e":"An attestation is a formal declaration that requirements are met, sometimes by internal management and sometimes by a third party. A penetration test simulates attacks. RCA determines incident causes. A BIA assesses disruption impact."},{"id":"S282","o":"5.4","d":5,"q":"Which concept refers to an organization's obligation to protect personal data in accordance with the purposes for which it was collected?","a":["Load balancing","Privacy compliance","High availability","Network segmentation"],"c":1,"e":"Privacy compliance requires handling personal data according to legal requirements and stated purposes. Availability, load balancing, and segmentation are technical concepts not specific to privacy obligations."},{"id":"S283","o":"5.4","d":5,"q":"A multinational company must comply with privacy laws that grant individuals the right to have their personal data deleted on request. What is this right commonly called?","a":["Right of way","Right of first refusal","Right to be forgotten","Right to audit"],"c":2,"e":"The right to be forgotten, or erasure, allows individuals to request deletion of their personal data. Right to audit is a contract clause. Right of first refusal and right of way are unrelated legal concepts."},{"id":"S284","o":"5.4","d":5,"q":"Which consequence of noncompliance can include restrictions imposed by a government on doing business with certain entities or countries?","a":["Increased bandwidth costs","Sanctions","Reputational damage only","Hardware failure"],"c":1,"e":"Sanctions are legal restrictions or penalties imposed by authorities. Reputational damage is a separate consequence. Bandwidth costs and hardware failures are unrelated to compliance."},{"id":"S285","o":"5.5","d":5,"q":"A company hires an independent firm to verify that its controls meet ISO 27001 requirements so it can be certified. What type of audit is this?","a":["Vulnerability scan","Penetration test","Internal self-assessment","External audit"],"c":3,"e":"An external audit is performed by an independent third party, often for certification. An internal self-assessment is performed by the organization itself. Penetration tests and vulnerability scans are technical assessments, not certification audits."},{"id":"S286","o":"5.5","d":5,"q":"A penetration tester is given full network diagrams, source code, and credentials before testing. What type of test is this?","a":["Unknown environment","Known environment","Partially known environment","Passive reconnaissance only"],"c":1,"e":"A known environment, or white box, test provides full information to the tester. An unknown environment provides none. A partially known environment provides limited information. Passive reconnaissance is information gathering without interacting with targets."},{"id":"S287","o":"5.5","d":5,"q":"During the reconnaissance phase of a penetration test, the tester gathers information from public websites, DNS records, and social media without directly interacting with the target systems. What is this called?","a":["Exploitation","Lateral movement","Passive reconnaissance","Active reconnaissance"],"c":2,"e":"Passive reconnaissance collects information without touching target systems. Active reconnaissance interacts with targets, such as port scanning. Exploitation takes advantage of vulnerabilities. Lateral movement moves within a compromised network."},{"id":"S288","o":"5.5","d":5,"q":"An internal audit team reviews whether the company is following its own access control policy. What is the PRIMARY purpose of this audit?","a":["Obtain cyber insurance automatically","Perform exploitation of production systems","Replace the need for external audits","Verify adherence to internal policies"],"c":3,"e":"Internal audits assess adherence to internal policies and highlight improvements. They do not replace external audits required for certification. They are not exploitation exercises. Insurance is not automatically granted."},{"id":"S289","o":"5.5","d":5,"q":"A red team attacks the organization's systems while a blue team defends, and afterwards both teams work together to improve detection and response. What is the collaborative approach called?","a":["Vulnerability scanning","Purple teaming","Bug bounty","Tabletop exercise"],"c":1,"e":"Purple teaming combines red and blue teams to share findings and improve defenses. A tabletop exercise is a discussion. A bug bounty rewards external researchers. Vulnerability scanning is automated weakness detection."},{"id":"S290","o":"5.5","d":5,"q":"A penetration tester performs a port scan and banner grabbing against the target's internet-facing servers. Which activity is this?","a":["Active reconnaissance","Privilege escalation","Persistence","Passive reconnaissance"],"c":0,"e":"Active reconnaissance involves directly probing target systems. Passive reconnaissance avoids interaction. Privilege escalation gains higher permissions after access. Persistence maintains access over time."},{"id":"S291","o":"5.5","d":5,"q":"Why should an organization obtain written authorization before conducting a penetration test against its systems or a provider's systems?","a":["Authorization removes the need for scope","Authorization makes the test faster","Authorization guarantees no vulnerabilities will be found","Testing without permission may be illegal and violate contracts"],"c":3,"e":"Unauthorized testing can breach laws and service agreements; written authorization establishes legal permission and scope. It does not affect speed, replace scoping, or determine findings."},{"id":"S292","o":"5.5","d":5,"q":"A regulator requires an organization to provide evidence that its security controls were reviewed by a qualified independent party. Which activity satisfies this requirement?","a":["Third-party attestation or audit","Results of an internal phishing simulation","A self-completed vendor questionnaire","A signed statement from the IT manager"],"c":0,"e":"Independent audits or attestations by qualified third parties provide credible evidence to regulators. A statement from the IT manager and a self-completed questionnaire lack independence. Phishing simulation results measure awareness, not the overall review of controls."},{"id":"S293","o":"5.6","d":5,"q":"The security team sends employees simulated phishing emails and provides immediate training to those who click the link. What is the PRIMARY goal?","a":["Collect employees' passwords for auditing","Test email server performance","Improve employees' ability to recognize phishing","Punish employees publicly"],"c":2,"e":"Phishing simulations with follow-up training build recognition skills and reduce risk. Public punishment undermines security culture. Collecting real passwords is inappropriate. Server performance is not the focus."},{"id":"S294","o":"5.6","d":5,"q":"An employee notices an unfamiliar person following staff through a secured door without badging in. What should security awareness training instruct the employee to do?","a":["Wait a week and then mention it informally","Report the incident to security according to procedure","Ignore it to avoid confrontation","Post about it on social media"],"c":1,"e":"Employees should promptly report suspicious activity through defined channels. Ignoring it allows potential intruders access. Social media posting is inappropriate. Delayed informal mention reduces response effectiveness."},{"id":"S295","o":"5.6","d":5,"q":"A company wants to measure whether its awareness program is effective. Which metric is MOST useful?","a":["Number of training sessions delivered","Total hours of video content produced","Percentage of staff who completed the course","Trends in phishing click and report rates"],"c":3,"e":"Changes in phishing click and reporting rates show actual behavior change, which is the goal of awareness. Session counts, completion percentages, and content hours measure activity and participation, not whether behavior improved."},{"id":"S296","o":"5.6","d":5,"q":"Which topic should be included in training for employees who frequently work from home and public locations?","a":["Writing secure code for internal applications","Home network security and screen privacy","Managing the corporate PKI root CA","Configuring the corporate firewall rule base"],"c":1,"e":"Remote workers need guidance on securing home networks, using the VPN, and preventing shoulder surfing in public places. Firewall configuration, secure coding, and PKI management are specialized role-based topics, not general guidance for remote employees."},{"id":"S297","o":"5.6","d":5,"q":"An employee receives an unexpected email from a colleague with an urgent request to buy gift cards for a client. What should training teach them to do FIRST?","a":["Verify the request through a separate known channel","Forward the email to all coworkers","Reply to the email asking if it is legitimate","Buy the gift cards immediately"],"c":0,"e":"Verifying through an independent channel, such as calling a known number, confirms legitimacy. Buying immediately risks fraud. Replying to the same email may reach the attacker. Forwarding spreads the message."},{"id":"S298","o":"5.6","d":5,"q":"Which behavior indicates a risky user that may require additional training?","a":["Reusing the same password everywhere","Locking the workstation when stepping away","Storing passwords in the approved password manager","Reporting suspicious emails to the security team"],"c":0,"e":"Password reuse increases the impact of any breach and indicates a need for additional training. Locking workstations, reporting suspicious emails, and using the approved password manager are positive behaviors."},{"id":"S299","o":"5.6","d":5,"q":"How often should security awareness training be delivered to remain effective?","a":["Only after a major breach","Once every three years during audits","Only once during onboarding","Regularly throughout the year"],"c":3,"e":"Continuous training with regular reinforcement keeps awareness current as threats evolve. One-time onboarding training fades over time. Waiting for a breach is reactive. A three-year cycle is far too infrequent for changing threats."},{"id":"S300","o":"5.6","d":5,"q":"A company provides different training content for developers, finance staff, and executives. What is the benefit of this approach?","a":["It eliminates the need for technical controls","It reduces the need for policies","It guarantees zero incidents","Training addresses role-specific risks and responsibilities"],"c":3,"e":"Role-based training targets the threats each group is most likely to face, such as secure coding or payment fraud. It does not replace policies or technical controls, and no training guarantees zero incidents."}];
